/**
 * Минимальные тесты для app/api/containers/route.ts (GET и POST).
 */

import { NextResponse } from "next/server";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";

jest.mock("@/lib/shared/api/require-auth", () => ({
  requireAuthAndTenant: jest.fn(),
}));
jest.mock("@/lib/shared/supabase/server", () => ({ createClient: jest.fn() }));
jest.mock("@/lib/containers/api", () => ({
  getContainersWithLocationRpc: jest.fn(),
}));
jest.mock("@/lib/shared/api/insert-entity-with-transition", () => ({
  insertEntityWithTransition: jest.fn(),
}));
jest.mock("@/lib/shared/api/search-index-queue", () => ({
  enqueueSearchIndexJob: jest.fn(),
}));

const requireAuthAndTenant = jest.requireMock("@/lib/shared/api/require-auth")
  .requireAuthAndTenant as jest.Mock;
const getContainersWithLocationRpc = jest.requireMock("@/lib/containers/api")
  .getContainersWithLocationRpc as jest.Mock;
const insertEntityWithTransition = jest.requireMock("@/lib/shared/api/insert-entity-with-transition")
  .insertEntityWithTransition as jest.Mock;
const enqueueSearchIndexJob = jest.requireMock("@/lib/shared/api/search-index-queue")
  .enqueueSearchIndexJob as jest.Mock;

const createGetRequest = (searchParams?: string) =>
  ({ url: `http://localhost/api/containers${searchParams ? `?${searchParams}` : ""}`, method: "GET", headers: new Headers() } as unknown as Request);

describe("GET /api/containers", () => {
  beforeEach(() => {
    jest.resetAllMocks();
    requireAuthAndTenant.mockResolvedValue({ tenantId: 1 });
    const mockSupabase = {};
    jest.requireMock("@/lib/shared/supabase/server").createClient.mockResolvedValue(mockSupabase);
  });

  it("возвращает 401, если пользователь не авторизован", async () => {
    requireAuthAndTenant.mockResolvedValue(
      NextResponse.json({ error: "Не авторизован" }, { status: HTTP_STATUS.UNAUTHORIZED })
    );
    const { GET } = await import("@/app/api/containers/route");
    const response = await GET(createGetRequest());
    expect(response.status).toBe(HTTP_STATUS.UNAUTHORIZED);
    expect(getContainersWithLocationRpc).not.toHaveBeenCalled();
  });

  it("возвращает 200 и data + totalCount при успешной загрузке", async () => {
    getContainersWithLocationRpc.mockResolvedValue({
      data: [
        {
          id: 1,
          name: "Box",
          entity_type_id: 1,
          entity_type_name: "Box",
          created_at: "2024-01-01T00:00:00Z",
          deleted_at: null,
          photo_url: null,
          items_count: 0,
          destination_type: null,
          destination_id: null,
          destination_name: null,
          moved_at: null,
          room_id: null,
          room_name: null,
          total_count: 1,
        },
      ],
      error: null,
    });
    const { GET } = await import("@/app/api/containers/route");
    const response = await GET(createGetRequest());
    expect(response.status).toBe(200);
    const body = await response.json();
    expect(body.data).toHaveLength(1);
    expect(body.data[0].name).toBe("Box");
    expect(body.totalCount).toBe(1);
  });

  it("возвращает 200 с data [] и totalCount 0 при пустом результате", async () => {
    getContainersWithLocationRpc.mockResolvedValue({ data: [], error: null });
    const { GET } = await import("@/app/api/containers/route");
    const response = await GET(createGetRequest());
    expect(response.status).toBe(200);
    const body = await response.json();
    expect(body.data).toEqual([]);
    expect(body.totalCount).toBe(0);
  });
});

describe("POST /api/containers", () => {
  beforeEach(() => {
    jest.resetAllMocks();
    requireAuthAndTenant.mockResolvedValue({ tenantId: 1 });
    jest.requireMock("@/lib/shared/supabase/server").createClient.mockResolvedValue({});
    enqueueSearchIndexJob.mockResolvedValue(null);
  });

  it("возвращает 400 при недопустимом destination_type", async () => {
    const { POST } = await import("@/app/api/containers/route");
    const request = {
      json: async () => ({ name: "C1", destination_type: "building", destination_id: 1 }),
      headers: new Headers(),
    } as unknown as Request;
    const response = await POST(request);
    expect(response.status).toBe(400);
    expect(insertEntityWithTransition).not.toHaveBeenCalled();
  });

  it("возвращает 201 при успешном создании с допустимым destination_type", async () => {
    insertEntityWithTransition.mockResolvedValue({ data: { id: 1, name: "C1" }, error: null });
    const { POST } = await import("@/app/api/containers/route");
    const request = {
      json: async () => ({ name: "C1", destination_type: "place", destination_id: 5 }),
      headers: new Headers(),
    } as unknown as Request;
    const response = await POST(request);
    expect(response.status).toBe(200);
    const body = await response.json();
    expect(body.data).toEqual({ id: 1, name: "C1" });
    expect(enqueueSearchIndexJob).toHaveBeenCalledWith(
      expect.anything(),
      {
        tenantId: 1,
        entityType: "container",
        entityId: 1,
      }
    );
  });
});

import { createSearchIndexConsumerHandler } from "@/supabase/functions/search-index-consumer/handler";

class MockHeaders {
  private readonly values = new Map<string, string>();

  constructor(init?: HeadersInit) {
    if (!init) {
      return;
    }

    for (const [key, value] of Object.entries(init as Record<string, string>)) {
      this.values.set(key.toLowerCase(), value);
    }
  }

  get(name: string): string | null {
    return this.values.get(name.toLowerCase()) ?? null;
  }
}

class MockResponse {
  readonly status: number;
  readonly headers: MockHeaders;

  constructor(
    private readonly body: string,
    init?: { status?: number; headers?: HeadersInit }
  ) {
    this.status = init?.status ?? 200;
    this.headers = new MockHeaders(init?.headers);
  }

  async json(): Promise<unknown> {
    return this.body ? JSON.parse(this.body) : null;
  }
}

Object.assign(globalThis, {
  Response: MockResponse,
});

const createRequest = (init?: {
  method?: string;
  body?: unknown;
  headers?: Record<string, string>;
}) =>
  ({
    method: init?.method ?? "POST",
    headers: new MockHeaders({
      "Content-Type": "application/json",
      ...(init?.headers ?? {}),
    }),
    json: async () =>
      init?.body === undefined
        ? {}
        : typeof init.body === "string"
          ? JSON.parse(init.body)
          : init.body,
  } as unknown as Request);

describe("search-index-consumer handler", () => {
  it("возвращает 405 для неподдерживаемого метода", async () => {
    const handler = createSearchIndexConsumerHandler({
      authorizeRequest: jest.fn(),
      readMessages: jest.fn(),
      deleteMessages: jest.fn(),
      syncJob: jest.fn(),
    });

    const response = await handler(createRequest({ method: "GET" }));

    expect(response.status).toBe(405);
  });

  it("возвращает ответ авторизации, если запрос не авторизован", async () => {
    const authorizeRequest = jest
      .fn()
      .mockResolvedValue(
        new MockResponse(JSON.stringify({ error: "Unauthorized" }), { status: 401 })
      );
    const handler = createSearchIndexConsumerHandler({
      authorizeRequest,
      readMessages: jest.fn(),
      deleteMessages: jest.fn(),
      syncJob: jest.fn(),
    });

    const response = await handler(createRequest());

    expect(response.status).toBe(401);
    expect(authorizeRequest).toHaveBeenCalledTimes(1);
  });

  it("обрабатывает batch и возвращает counters", async () => {
    const readMessages = jest.fn().mockResolvedValue([
      {
        msgId: 1,
        readCount: 0,
        enqueuedAt: "a",
        visibleAt: "b",
        message: { tenantId: 1, entityType: "item", entityId: 2 },
      },
      {
        msgId: 2,
        readCount: 0,
        enqueuedAt: "a",
        visibleAt: "b",
        message: { tenantId: 1, entityType: "item", entityId: 2 },
      },
      {
        msgId: 3,
        readCount: 0,
        enqueuedAt: "a",
        visibleAt: "b",
        message: { tenantId: 1, entityType: "container", entityId: 8 },
      },
    ]);
    const deleteMessages = jest.fn().mockResolvedValue(3);
    const syncJob = jest.fn().mockResolvedValue(undefined);
    const handler = createSearchIndexConsumerHandler({
      authorizeRequest: jest.fn().mockResolvedValue(null),
      readMessages,
      deleteMessages,
      syncJob,
      logError: jest.fn(),
    });

    const response = await handler(
      createRequest({
        body: { batchSize: 50, visibilityTimeoutSeconds: 120 },
      })
    );

    expect(response.status).toBe(200);
    expect(readMessages).toHaveBeenCalledWith({
      batchSize: 50,
      visibilityTimeoutSeconds: 120,
    });

    const body = await response.json();
    expect(body).toEqual({
      read: 3,
      valid: 2,
      invalid: 0,
      duplicates: 1,
      attempted: 2,
      processed: 2,
      failed: 0,
      deleted: 3,
    });
  });

  it("возвращает 500 и логирует ошибку consumer-а", async () => {
    const logError = jest.fn();
    const handler = createSearchIndexConsumerHandler({
      authorizeRequest: jest.fn().mockResolvedValue(null),
      readMessages: jest.fn().mockRejectedValue(new Error("queue down")),
      deleteMessages: jest.fn(),
      syncJob: jest.fn(),
      logError,
    });

    const response = await handler(createRequest());

    expect(response.status).toBe(500);
    expect(logError).toHaveBeenCalled();

    const body = await response.json();
    expect(body.error).toBe("queue down");
  });
});

"use client";

import { useEffect, useState } from "react";
import { useUser } from "@/lib/users/context";
import { updatePassword } from "@/lib/auth/api";
import { useTheme } from "next-themes";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Loader2, Moon, Sun } from "lucide-react";
import { PageHeader } from "@/components/layout/page-header";
import { FieldGroup, FieldLabel, Field } from "@/components/ui/field";

const MIN_PASSWORD_LENGTH = 6;

export default function AccountPage() {
  const { user, isLoading: isUserLoading } = useUser();
  const { resolvedTheme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleThemeToggle = () => {
    setTheme(resolvedTheme === "dark" ? "light" : "dark");
  };

  const ThemeIcon = mounted ? (resolvedTheme === "dark" ? Moon : Sun) : null;

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);

    if (newPassword.length < MIN_PASSWORD_LENGTH) {
      setError(`Пароль должен быть не менее ${MIN_PASSWORD_LENGTH} символов`);
      return;
    }
    if (newPassword !== confirmPassword) {
      setError("Пароли не совпадают");
      return;
    }

    setIsLoading(true);
    try {
      const result = await updatePassword(newPassword);
      if (result.error) {
        setError(result.error);
        return;
      }
      setSuccess("Пароль успешно изменён");
      setNewPassword("");
      setConfirmPassword("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Произошла ошибка");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-4">
      <PageHeader title="Аккаунт" />

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            Почта
          </CardTitle>
        </CardHeader>
        <CardContent>
          {isUserLoading ? (
            <Skeleton className="h-8 w-full" />
          ) : (
            <Input type="email" value={user?.email ?? ""} disabled />
          )}
          <p className="text-sm text-muted-foreground mt-2">Почту нельзя изменить</p>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Тема</CardTitle>
          <CardDescription>
            Переключение светлой и тёмной темы оформления
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Button
            type="button"
            variant="outline"
            onClick={handleThemeToggle}
            className="gap-2"
          >
            {ThemeIcon ? <ThemeIcon className="h-4 w-4" /> : null}
            Сменить тему
          </Button>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Смена пароля</CardTitle>
          <CardDescription>
            Введите новый пароль (не менее {MIN_PASSWORD_LENGTH} символов)
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form id="account-password-form" onSubmit={handleSubmit} className="flex flex-col gap-4">
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="account-new-password">
                  Новый пароль
                </FieldLabel>
                <Input
                  id="account-new-password"
                  type="password"
                  autoComplete="new-password"
                  placeholder="••••••••"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  disabled={isLoading}
                  aria-label="Новый пароль"
                  aria-invalid={!!error}
                  className="w-full max-w-sm"
                />
              </Field>

              <Field>
                <FieldLabel htmlFor="account-confirm-password">
                  Повторите пароль
                </FieldLabel>
                <Input
                  id="account-confirm-password"
                  type="password"
                  autoComplete="new-password"
                  placeholder="••••••••"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  disabled={isLoading}
                  aria-label="Повторите пароль"
                  aria-invalid={!!error}
                  className="w-full max-w-sm"
                />
              </Field>
            </FieldGroup>
            {error && (
              <p className="text-sm text-destructive" role="alert">
                {error}
              </p>
            )}
            {success && (
              <p className="text-sm text-green-600 dark:text-green-400" role="status">
                {success}
              </p>
            )}

          </form>
        </CardContent>
        <CardFooter>
          <Button type="submit" form="account-password-form" disabled={isLoading}>
            {isLoading ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
                <span>Сохранение...</span>
              </>
            ) : (
              <span>Сохранить пароль</span>
            )}
          </Button>
        </CardFooter>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";

import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field";
import { EntityDetailSkeleton } from "@/components/entity-detail/entity-detail-skeleton";
import { EntityDetailError } from "@/components/entity-detail/entity-detail-error";
import { TransitionsTable } from "@/components/entity-detail/transitions-table";
import MoveEntityForm from "@/components/forms/move-entity-form";
import { getEntityDisplayName } from "@/lib/entities/helpers/display-name";
import { itemsEntityConfig } from "@/lib/entities/items/entity-config";
import { EntityImageCard } from "@/components/entity-detail/entity-image-card";
import { ErrorMessage } from "@/components/common/error-message";
import { useItemDetail } from "@/lib/entities/hooks/use-item-detail";
import { updateItem } from "@/lib/entities/api";
import { EntityTypeSelect } from "@/components/fields/entity-type-select";
import { PriceInput, type PriceValue } from "@/components/fields/price-input";
import { DatePicker } from "@/components/fields/date-picker";
import { PageHeader } from "@/components/layout/page-header";

export default function ItemDetailPage() {
  const {
    item,
    transitions,
    isLoading,
    isLoadingTransitions,
    error,
    isMoveDialogOpen,
    setIsMoveDialogOpen,
    handleEditSuccess,
    handleMoveSuccess,
    entityLabel,
    headerActions,
  } = useItemDetail();

  const [name, setName] = useState("");
  const [itemTypeId, setItemTypeId] = useState("");
  const [price, setPrice] = useState<PriceValue | null>(null);
  const [currentValue, setCurrentValue] = useState<PriceValue | null>(null);
  const [quantity, setQuantity] = useState<number>(1);
  const [purchaseDate, setPurchaseDate] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  useEffect(() => {
    if (item) {
      setName(item.name ?? "");
      setItemTypeId(item.item_type_id?.toString() ?? "");
      setPrice(
        item.price?.amount != null && item.price?.currency
          ? { amount: item.price.amount, currency: item.price.currency }
          : null
      );
      setCurrentValue(
        item.currentValue?.amount != null && item.currentValue?.currency
          ? { amount: item.currentValue.amount, currency: item.currentValue.currency }
          : null
      );
      setQuantity(item.quantity ?? 1);
      setPurchaseDate(item.purchaseDate ?? "");
    }
  }, [item]);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!item) return;
    setFormError(null);
    setIsSubmitting(true);

    try {
      const response = await updateItem(item.id, {
        name: name.trim() || undefined,
        item_type_id: itemTypeId ? parseInt(itemTypeId) : null,
        price_amount: price?.amount ?? null,
        price_currency: price?.currency ?? null,
        current_value_amount: currentValue?.amount ?? null,
        current_value_currency: currentValue?.currency ?? null,
        quantity: quantity >= 1 ? quantity : 1,
        purchase_date: purchaseDate.trim() || null,
      });

      if (response.error) {
        throw new Error(response.error);
      }

      toast.success("Вещь успешно обновлена");
      handleEditSuccess();
    } catch (err) {
      setFormError(
        err instanceof Error ? err.message : "Произошла ошибка при сохранении"
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  if (error && !isLoading) {
    return <EntityDetailError error={error} entityName={entityLabel} />;
  }

  if (!isLoading && !item) {
    return null;
  }

  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        isLoading={isLoading}
        title={item?.name ?? (item ? `Вещь #${item.id}` : "Вещь")}
        ancestors={[
          { label: "Вещи", href: "/items" },
        ]}
        actions={headerActions}
      />
      {isLoading ? (
        <EntityDetailSkeleton />
      ) : item ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="flex flex-col gap-6">
          <Card>
            <CardHeader>
              <CardTitle>Редактирование вещи</CardTitle>
              <CardDescription>ID: #{item.id}</CardDescription>
            </CardHeader>
            <CardContent>
              <form id={`item-form-${item.id}`} onSubmit={handleSubmit}>
                <FieldGroup>
                  <Field>
                    <FieldLabel htmlFor={`item-name-${item.id}`}>Название вещи</FieldLabel>
                    <Input
                      id={`item-name-${item.id}`}
                      type="text"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      placeholder="Введите название вещи"
                      disabled={isSubmitting}
                    />
                  </Field>

                  <EntityTypeSelect
                    type="item"
                    value={itemTypeId ? parseInt(itemTypeId) : null}
                    onValueChange={(v) => setItemTypeId(v ?? "")}
                  />

                  <PriceInput
                    value={price}
                    onChange={setPrice}
                    id={`item-price-${item.id}`}
                    disabled={isSubmitting}
                  />

                  <PriceInput
                    value={currentValue}
                    onChange={setCurrentValue}
                    id={`item-current-value-${item.id}`}
                    label="Текущая оценочная стоимость (необязательно)"
                    disabled={isSubmitting}
                  />

                  <Field>
                    <FieldLabel htmlFor={`item-quantity-${item.id}`}>Количество</FieldLabel>
                    <Input
                      id={`item-quantity-${item.id}`}
                      type="number"
                      min={1}
                      value={quantity}
                      onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value, 10) || 1))}
                      disabled={isSubmitting}
                    />
                  </Field>

                  <DatePicker
                    value={purchaseDate}
                    onChange={setPurchaseDate}
                    id={`item-purchase-date-${item.id}`}
                    label="Дата покупки"
                    placeholder="Выберите дату"
                    disabled={isSubmitting}
                  />

                  <ErrorMessage message={formError ?? ""} />
                </FieldGroup>
              </form>
            </CardContent>
            <CardFooter className="flex justify-between">
              <Button type="submit" form={`item-form-${item.id}`} disabled={isSubmitting}>
                {isSubmitting ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Сохранение...
                  </>
                ) : (
                  "Сохранить"
                )}
              </Button>
            </CardFooter>
          </Card>

          <EntityImageCard
            entityType="item"
            entityId={item.id}
            entityName={name}
            photoUrl={item.photo_url ?? null}
            onPhotoChange={async (url) => {
              const res = await updateItem(item.id, { photo_url: url });
              if (res.error) throw new Error(res.error);
              handleEditSuccess();
            }}
          />
          </div>

          <div className="flex flex-col gap-2">
            <Card>
              <CardHeader>
                <CardTitle>История перемещений</CardTitle>
              </CardHeader>
              <CardContent>
                <TransitionsTable
                  transitions={transitions}
                  emptyMessage="История перемещений пуста"
                  isLoading={isLoadingTransitions}
                />
              </CardContent>
            </Card>
          </div>

          {isMoveDialogOpen && item && (
            <MoveEntityForm
              title={itemsEntityConfig.labels.moveTitle}
              entityDisplayName={getEntityDisplayName("item", item.id, item.name)}
              destinationTypes={itemsEntityConfig.move?.destinationTypes ?? ["room", "place", "container"]}
              buildPayload={(destinationType, destinationId) => ({
                item_id: item.id,
                destination_type: destinationType,
                destination_id: destinationId,
              })}
              getSuccessMessage={itemsEntityConfig.labels.moveSuccess}
              getErrorMessage={() => itemsEntityConfig.labels.moveError}
              open={isMoveDialogOpen}
              onOpenChange={setIsMoveDialogOpen}
              onSuccess={handleMoveSuccess}
            />
          )}
        </div>
      ) : null}
    </div>
  );
}

import { NextResponse } from 'next/server'
// The client you created from the Server-Side Auth instructions
import { createClient } from "@/lib/shared/supabase/server"

export async function GET(request: Request) {
  const requestUrl = new URL(request.url)
  const { searchParams, origin } = requestUrl
  const code = searchParams.get('code')
  // if "next" is in param, use it as the redirect URL
  let next = searchParams.get('next') ?? '/'
  if (!next.startsWith('/')) {
    // if "next" is not a relative URL, use the default
    next = '/'
  }

  // Логирование для отладки (только в development)
  const host = request.headers.get('host')
  const forwardedHost = request.headers.get('x-forwarded-host')
  const forwardedProto = request.headers.get('x-forwarded-proto')
  const referer = request.headers.get('referer')

  if (process.env.NODE_ENV === "development") {
    console.log('🔍 Callback route called:', {
      origin,
      host,
      forwardedHost,
      forwardedProto,
      referer,
      requestUrl: requestUrl.toString(),
      allHeaders: Object.fromEntries(request.headers.entries()),
    });
  }

  if (code) {
    const supabase = await createClient()
    const { error } = await supabase.auth.exchangeCodeForSession(code)
    if (!error) {
      // Определяем правильный URL для редиректа
      let redirectUrl: string;

      // Приоритет 1: x-forwarded-host (для dev tunnels, прокси, load balancers)
      if (forwardedHost) {
        const protocol = forwardedProto || 'https'
        redirectUrl = `${protocol}://${forwardedHost}${next}`
        if (process.env.NODE_ENV === "development") console.log('✅ Using x-forwarded-host:', redirectUrl);
      } 
      // Приоритет 2: host из заголовков (может быть dev tunnels домен)
      else if (host && !host.includes('localhost') && !host.includes('127.0.0.1')) {
        const protocol = forwardedProto || (host.includes('devtunnels.ms') ? 'https' : 'http')
        redirectUrl = `${protocol}://${host}${next}`
        if (process.env.NODE_ENV === "development") console.log('✅ Using host header:', redirectUrl);
      }
      // Приоритет 3: referer (откуда пришел запрос)
      else if (referer) {
        try {
          const refererUrl = new URL(referer)
          if (!refererUrl.origin.includes('localhost')) {
            redirectUrl = `${refererUrl.origin}${next}`
            if (process.env.NODE_ENV === "development") console.log('✅ Using referer:', redirectUrl);
          } else {
            throw new Error('Referer is localhost')
          }
        } catch {
          // Если не удалось распарсить referer или это localhost, используем переменную окружения
          const baseUrl = process.env.NEXT_PUBLIC_APP_URL
          if (baseUrl && !baseUrl.includes('localhost')) {
            redirectUrl = baseUrl.startsWith('http') ? `${baseUrl}${next}` : `https://${baseUrl}${next}`
            if (process.env.NODE_ENV === "development") console.log('✅ Using NEXT_PUBLIC_APP_URL:', redirectUrl);
          } else {
            redirectUrl = `${origin}${next}`
            if (process.env.NODE_ENV === "development") console.log('⚠️ Fallback to origin:', redirectUrl);
          }
        }
      }
      // Приоритет 4: origin (если не localhost)
      else if (origin && !origin.includes('localhost') && !origin.includes('127.0.0.1')) {
        redirectUrl = `${origin}${next}`
        if (process.env.NODE_ENV === "development") console.log('✅ Using origin:', redirectUrl);
      }
      // Приоритет 5: переменная окружения
      else {
        const baseUrl = process.env.NEXT_PUBLIC_APP_URL
        if (baseUrl && !baseUrl.includes('localhost')) {
          redirectUrl = baseUrl.startsWith('http') ? `${baseUrl}${next}` : `https://${baseUrl}${next}`
          if (process.env.NODE_ENV === "development") console.log('✅ Using NEXT_PUBLIC_APP_URL (fallback):', redirectUrl);
        } else {
          redirectUrl = `${origin}${next}`
          if (process.env.NODE_ENV === "development") console.log('⚠️ Final fallback to origin:', redirectUrl);
        }
      }

      if (process.env.NODE_ENV === "development") console.log('🚀 Redirecting to:', redirectUrl);
      return NextResponse.redirect(redirectUrl)
    } else {
      console.error('Supabase exchangeCodeForSession error:', error)
    }
  }

  // return the user to an error page with instructions
  // Используем ту же логику для определения URL ошибки
  let errorRedirectUrl: string
  if (forwardedHost) {
    errorRedirectUrl = `${forwardedProto || 'https'}://${forwardedHost}/auth/auth-code-error`
  } else if (host && !host.includes('localhost')) {
    errorRedirectUrl = `https://${host}/auth/auth-code-error`
  } else {
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL
    if (baseUrl && !baseUrl.includes('localhost')) {
      errorRedirectUrl = baseUrl.startsWith('http') ? `${baseUrl}/auth/auth-code-error` : `https://${baseUrl}/auth/auth-code-error`
    } else {
      errorRedirectUrl = `${origin}/auth/auth-code-error`
    }
  }

  if (process.env.NODE_ENV === "development") console.log('❌ Error redirect to:', errorRedirectUrl);
  return NextResponse.redirect(errorRedirectUrl)
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { parseId } from "@/lib/shared/api/parse-id";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { enqueueSearchIndexJob } from "@/lib/shared/api/search-index-queue";
import { logError } from "@/lib/shared/logger";
/** Имена таблиц API (путь [table]), не путать с EntityTypeName (item, place, ...). */
type ApiTableName = "items" | "places" | "containers" | "rooms" | "buildings" | "furniture";

const ALLOWED_TABLES: readonly ApiTableName[] = ["items", "places", "containers", "rooms", "buildings", "furniture"];

type DuplicateParams =
  | { params: Promise<{ table: string; id: string }> }
  | { params: { table: string; id: string } };

type SourceRow = {
  id: number;
  name: string | null;
  photo_url: string | null;
  deleted_at: string | null;
  item_type_id?: number | null;
  price_amount?: number | null;
  price_currency?: string | null;
  current_value_amount?: number | null;
  current_value_currency?: string | null;
  quantity?: number | null;
  purchase_date?: string | null;
  entity_type_id?: number | null;
  room_type_id?: number | null;
  building_type_id?: number | null;
  furniture_type_id?: number | null;
  building_id?: number | null;
  room_id?: number | null;
};

type LastTransitionRow = {
  destination_type: "room" | "place" | "container" | "furniture" | null;
  destination_id: number | null;
};

const SOURCE_SELECT_BY_TABLE: Record<ApiTableName, string> = {
  items: "id, name, photo_url, item_type_id, price_amount, price_currency, current_value_amount, current_value_currency, quantity, purchase_date, deleted_at",
  places: "id, name, photo_url, entity_type_id, deleted_at",
  containers: "id, name, photo_url, entity_type_id, deleted_at",
  rooms: "id, name, photo_url, room_type_id, building_id, deleted_at",
  buildings: "id, name, photo_url, building_type_id, deleted_at",
  furniture: "id, name, photo_url, room_id, furniture_type_id, price_amount, price_currency, current_value_amount, current_value_currency, purchase_date, deleted_at",
};

const TRANSITION_ID_COLUMN_BY_TABLE: Partial<Record<ApiTableName, "item_id" | "place_id" | "container_id">> = {
  items: "item_id",
  places: "place_id",
  containers: "container_id",
};

const getDuplicateName = (name: string | null): string | null => {
  const normalizedName = name?.trim();
  if (!normalizedName) return null;
  return `${normalizedName} (копия)`;
};

export async function POST(
  request: NextRequest,
  context: DuplicateParams
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const supabase = await createClient();
    const resolvedParams = await Promise.resolve(context.params);
    const table = resolvedParams.table as ApiTableName;

    if (!ALLOWED_TABLES.includes(table)) {
      return NextResponse.json({ error: "Недопустимая таблица" }, { status: HTTP_STATUS.BAD_REQUEST });
    }

    const idResult = parseId(resolvedParams.id, { entityLabel: "сущности" });
    if (idResult instanceof NextResponse) return idResult;
    const sourceId = idResult.id;

    const { data: sourceEntity, error: sourceError } = await supabase
      .from(table)
      .select(SOURCE_SELECT_BY_TABLE[table])
      .eq("id", sourceId)
      .maybeSingle();

    if (sourceError) {
      return NextResponse.json({ error: sourceError.message }, { status: HTTP_STATUS.INTERNAL_SERVER_ERROR });
    }

    if (!sourceEntity) {
      return NextResponse.json({ error: "Сущность не найдена" }, { status: HTTP_STATUS.NOT_FOUND });
    }

    const source = sourceEntity as unknown as SourceRow;
    if (source.deleted_at) {
      return NextResponse.json(
        { error: "Нельзя дублировать удаленную сущность" },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }

    const duplicateName = getDuplicateName(source.name);

    let insertData: Record<string, unknown> = {
      name: duplicateName,
      photo_url: source.photo_url || null,
      tenant_id: tenantId,
    };

    if (table === "items") {
      insertData = {
        ...insertData,
        item_type_id: source.item_type_id ?? null,
        price_amount: source.price_amount ?? null,
        price_currency: source.price_currency ?? null,
        current_value_amount: source.current_value_amount ?? null,
        current_value_currency: source.current_value_currency ?? null,
        quantity: source.quantity ?? 1,
        purchase_date: source.purchase_date ?? null,
      };
    } else if (table === "rooms") {
      insertData = {
        ...insertData,
        room_type_id: source.room_type_id ?? null,
        building_id: source.building_id ?? null,
      };
    } else if (table === "buildings") {
      insertData = {
        ...insertData,
        building_type_id: source.building_type_id ?? null,
      };
    } else if (table === "furniture") {
      insertData = {
        ...insertData,
        room_id: source.room_id ?? null,
        furniture_type_id: source.furniture_type_id ?? null,
        price_amount: source.price_amount ?? null,
        price_currency: source.price_currency ?? null,
        current_value_amount: source.current_value_amount ?? null,
        current_value_currency: source.current_value_currency ?? null,
        purchase_date: source.purchase_date ?? null,
      };
    } else {
      insertData = {
        ...insertData,
        entity_type_id: source.entity_type_id ?? null,
      };
    }

    const { data: duplicatedEntity, error: insertError } = await supabase
      .from(table)
      .insert(insertData)
      .select()
      .single();

    if (insertError || !duplicatedEntity) {
      return NextResponse.json(
        { error: insertError?.message || "Не удалось создать копию" },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    const transitionIdColumn = TRANSITION_ID_COLUMN_BY_TABLE[table];
    if (transitionIdColumn) {
      const { data: lastTransition, error: transitionLoadError } = await supabase
        .from("transitions")
        .select("destination_type, destination_id")
        .eq(transitionIdColumn, sourceId)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (transitionLoadError) {
        await supabase.from(table).delete().eq("id", duplicatedEntity.id);
        return NextResponse.json({ error: transitionLoadError.message }, { status: HTTP_STATUS.INTERNAL_SERVER_ERROR });
      }

      const transition = lastTransition as LastTransitionRow | null;
      // Места могут быть только в мебели — пропускаем устаревшие room-переходы
      const skipTransition =
        table === "places" && transition?.destination_type === "room";
      if (transition?.destination_type && transition.destination_id && !skipTransition) {
        const { error: transitionInsertError } = await supabase
          .from("transitions")
          .insert({
            [transitionIdColumn]: duplicatedEntity.id,
            destination_type: transition.destination_type,
            destination_id: transition.destination_id,
            tenant_id: tenantId,
          });

        if (transitionInsertError) {
          await supabase.from(table).delete().eq("id", duplicatedEntity.id);
          return NextResponse.json({ error: transitionInsertError.message }, { status: HTTP_STATUS.INTERNAL_SERVER_ERROR });
        }
      }
    }

    if (table === "items") {
      try {
        await enqueueSearchIndexJob(supabase, {
          tenantId,
          entityType: "item",
          entityId: duplicatedEntity.id,
        });
      } catch (error) {
        logError("Ошибка постановки вещи в очередь индексации после дублирования:", error);
      }
    }

    if (table === "containers") {
      try {
        await enqueueSearchIndexJob(supabase, {
          tenantId,
          entityType: "container",
          entityId: duplicatedEntity.id,
        });
      } catch (error) {
        logError("Ошибка постановки контейнера в очередь индексации после дублирования:", error);
      }
    }

    return NextResponse.json(
      {
        data: duplicatedEntity,
      },
      { status: HTTP_STATUS.CREATED }
    );
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка дублирования сущности:",
      defaultMessage: "Произошла ошибка при дублировании сущности",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { requireIdParam } from "@/lib/shared/api/require-id-param";
import { validateItemMoney } from "@/lib/shared/api/validate-item-money";
import {
  FURNITURE_DETAIL_PLACES_LIMIT,
  FURNITURE_DETAIL_CHILDREN_LIMIT,
} from "@/lib/shared/api/constants";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { getPlacesWithRoomRpc } from "@/lib/places/api";
import { getItemsWithRoomRpc } from "@/lib/entities/api";
import { getContainersWithLocationRpc } from "@/lib/containers/api";
import type { Furniture } from "@/types/entity";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const idResult = await requireIdParam(params, { entityLabel: "мебели" });
    if (idResult instanceof NextResponse) return idResult;
    const furnitureId = idResult.id;
    const supabase = await createClient();

    const { data: furnitureData, error: furnitureError } = await supabase
      .from("furniture")
      .select("id, name, room_id, photo_url, created_at, deleted_at, furniture_type_id, price_amount, price_currency, current_value_amount, current_value_currency, purchase_date")
      .eq("id", furnitureId)
      .eq("tenant_id", tenantId)
      .single();

    if (furnitureError || !furnitureData) {
      return NextResponse.json(
        { error: furnitureError?.message ?? "Мебель не найдена" },
        { status: HTTP_STATUS.NOT_FOUND }
      );
    }

    let roomName: string | null = null;
    let furnitureTypeName: string | null = null;
    if (furnitureData.room_id) {
      const { data: roomRow } = await supabase
        .from("rooms")
        .select("name")
        .eq("id", furnitureData.room_id)
        .single();
      roomName = roomRow?.name ?? null;
    }
    if (furnitureData.furniture_type_id) {
      const { data: typeRow } = await supabase
        .from("entity_types")
        .select("name")
        .eq("id", furnitureData.furniture_type_id)
        .single();
      furnitureTypeName = typeRow?.name ?? null;
    }

    const furniture: Furniture = {
      id: furnitureData.id,
      name: furnitureData.name,
      photo_url: furnitureData.photo_url,
      created_at: furnitureData.created_at,
      deleted_at: furnitureData.deleted_at,
      room_id: furnitureData.room_id,
      room: furnitureData.room_id != null ? { id: furnitureData.room_id, name: roomName ?? null } : null,
      furniture_type_id: furnitureData.furniture_type_id ?? null,
      furniture_type: furnitureTypeName ? { name: furnitureTypeName } : null,
      price:
        furnitureData.price_amount != null && furnitureData.price_currency
          ? { amount: furnitureData.price_amount, currency: furnitureData.price_currency }
          : null,
      currentValue:
        furnitureData.current_value_amount != null && furnitureData.current_value_currency
          ? { amount: furnitureData.current_value_amount, currency: furnitureData.current_value_currency }
          : null,
      purchaseDate: furnitureData.purchase_date ?? null,
    };

    const { data: placesData } = await getPlacesWithRoomRpc(supabase, {
      search_query: null,
      show_deleted: false,
      page_limit: FURNITURE_DETAIL_PLACES_LIMIT,
      page_offset: 0,
      sort_by: "created_at",
      sort_direction: "desc",
      filter_entity_type_id: null,
      filter_room_id: null,
      filter_furniture_id: furnitureId,
      filter_tenant_id: tenantId,
    });

    const places = (placesData ?? []).map((p: { id: number; name: string | null; entity_type_id: number | null }) => ({
      id: p.id,
      name: p.name,
      entity_type_id: p.entity_type_id ?? null,
    }));

    const [{ data: itemsData }, { data: containersData }] = await Promise.all([
      getItemsWithRoomRpc(supabase, {
        search_query: null,
        show_deleted: false,
        page_limit: FURNITURE_DETAIL_CHILDREN_LIMIT,
        page_offset: 0,
        location_type: "furniture",
        room_id: null,
        place_id: null,
        container_id: null,
        furniture_id: furnitureId,
        has_photo: null,
        sort_by: "created_at",
        sort_direction: "desc",
        filter_tenant_id: tenantId,
      }),
      getContainersWithLocationRpc(supabase, {
        search_query: null,
        show_deleted: false,
        page_limit: FURNITURE_DETAIL_CHILDREN_LIMIT,
        page_offset: 0,
        sort_by: "created_at",
        sort_direction: "desc",
        p_entity_type_id: null,
        p_has_items: null,
        p_destination_type: "furniture",
        filter_tenant_id: tenantId,
        p_furniture_id: furnitureId,
      }),
    ]);

    const items = (itemsData ?? []).map((item: { id: number; name: string | null; photo_url: string | null; created_at: string }) => ({
      id: item.id,
      name: item.name,
      photo_url: item.photo_url,
      created_at: item.created_at,
    }));
    const containers = (containersData ?? []).map((c: { id: number; name: string | null; photo_url: string | null; created_at: string }) => ({
      id: c.id,
      name: c.name,
      photo_url: c.photo_url,
      created_at: c.created_at,
    }));

    return NextResponse.json({
      data: { furniture, places, items, containers },
    });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка загрузки данных мебели:",
      defaultMessage: "Произошла ошибка при загрузке данных",
    });
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const idResult = await requireIdParam(params, { entityLabel: "мебели" });
    if (idResult instanceof NextResponse) return idResult;
    const furnitureId = idResult.id;
    const supabase = await createClient();

    const body = await request.json();
    const {
      name,
      room_id,
      furniture_type_id,
      photo_url,
      price_amount,
      price_currency,
      current_value_amount,
      current_value_currency,
      purchase_date,
    } = body;

    const moneyValidation = validateItemMoney(body);
    if (moneyValidation instanceof NextResponse) return moneyValidation;

    const updateData: {
      name?: string | null;
      room_id?: number;
      furniture_type_id?: number | null;
      photo_url?: string | null;
      price_amount?: number | null;
      price_currency?: string | null;
      current_value_amount?: number | null;
      current_value_currency?: string | null;
      purchase_date?: string | null;
    } = {};
    if (name !== undefined) updateData.name = name?.trim() || null;
    if (room_id !== undefined) updateData.room_id = Number(room_id);
    if (furniture_type_id !== undefined)
      updateData.furniture_type_id = furniture_type_id != null ? (Number(furniture_type_id) || null) : null;
    if (photo_url !== undefined) updateData.photo_url = photo_url || null;
    if (price_amount !== undefined) updateData.price_amount = moneyValidation.price_amount;
    if (price_currency !== undefined) updateData.price_currency = moneyValidation.price_currency;
    if (current_value_amount !== undefined)
      updateData.current_value_amount = moneyValidation.current_value_amount;
    if (current_value_currency !== undefined)
      updateData.current_value_currency = moneyValidation.current_value_currency;
    if (purchase_date !== undefined)
      updateData.purchase_date = purchase_date && purchase_date.trim() ? purchase_date.trim() : null;

    const { data, error } = await supabase
      .from("furniture")
      .update(updateData)
      .eq("id", furnitureId)
      .select()
      .single();

    if (error) {
      return NextResponse.json(
        { error: error.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    return NextResponse.json({ data });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка обновления мебели:",
      defaultMessage: "Произошла ошибка при обновлении мебели",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { requireIdParam } from "@/lib/shared/api/require-id-param";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { validateItemMoney } from "@/lib/shared/api/validate-item-money";
import { normalizeEntityTypeRelation } from "@/lib/shared/api/normalize-entity-type-relation";
import type { Item } from "@/types/entity";
import { enqueueSearchIndexJob } from "@/lib/shared/api/search-index-queue";
import { logError } from "@/lib/shared/logger";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const idResult = await requireIdParam(params, { entityLabel: "вещи" });
    if (idResult instanceof NextResponse) return idResult;
    const itemId = idResult.id;
    const supabase = await createClient();

    const { data: itemData, error: itemError } = await supabase
      .from("items")
      .select("id, name, created_at, deleted_at, photo_url, item_type_id, price_amount, price_currency, current_value_amount, current_value_currency, quantity, purchase_date, entity_types(name)")
      .eq("id", itemId)
      .eq("tenant_id", tenantId)
      .single();

    if (itemError) {
      return NextResponse.json(
        { error: itemError.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    if (!itemData) {
      const body: { error: string; debug?: { itemId: number; tenantId: number } } = { error: "Вещь не найдена" };
      if (process.env.NODE_ENV === "development") {
        body.debug = { itemId, tenantId };
      }
      return NextResponse.json(body, { status: HTTP_STATUS.NOT_FOUND });
    }

    const itemEntityType = normalizeEntityTypeRelation(itemData.entity_types);
    const { price_amount, price_currency, current_value_amount, current_value_currency, quantity, purchase_date, ...restItemData } = itemData;
    delete (restItemData as any).entity_types;
    const item: Item = {
      ...restItemData,
      item_type_id: itemData.item_type_id ?? null,
      item_type: itemEntityType?.name ? { name: itemEntityType.name } : null,
      price:
        price_amount != null && price_currency
          ? { amount: price_amount, currency: price_currency }
          : null,
      currentValue:
        current_value_amount != null && current_value_currency
          ? { amount: current_value_amount, currency: current_value_currency }
          : null,
      quantity: quantity ?? null,
      purchaseDate: purchase_date ?? null,
    };

    return NextResponse.json({ data: item });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка загрузки данных вещи:",
      defaultMessage: "Произошла ошибка при загрузке данных",
    });
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const idResult = await requireIdParam(params, { entityLabel: "вещи" });
    if (idResult instanceof NextResponse) return idResult;
    const itemId = idResult.id;
    const supabase = await createClient();

    const body = await request.json();
    const { name, photo_url, item_type_id, quantity, purchase_date } = body;

    const moneyValidation = validateItemMoney(body);
    if (moneyValidation instanceof NextResponse) return moneyValidation;

    const updateData: {
      name?: string | null;
      photo_url?: string | null;
      item_type_id?: number | null;
      price_amount?: number | null;
      price_currency?: string | null;
      current_value_amount?: number | null;
      current_value_currency?: string | null;
      quantity?: number | null;
      purchase_date?: string | null;
    } = {};
    if (name !== undefined) updateData.name = name?.trim() || null;
    if (photo_url !== undefined) updateData.photo_url = photo_url || null;
    if (item_type_id !== undefined) updateData.item_type_id = item_type_id != null ? (Number(item_type_id) || null) : null;
    if (body.price_amount !== undefined) updateData.price_amount = moneyValidation.price_amount;
    if (body.price_currency !== undefined) updateData.price_currency = moneyValidation.price_currency;
    if (body.current_value_amount !== undefined) updateData.current_value_amount = moneyValidation.current_value_amount;
    if (body.current_value_currency !== undefined) updateData.current_value_currency = moneyValidation.current_value_currency;
    if (quantity !== undefined) updateData.quantity = quantity != null && quantity !== "" ? Number(quantity) : 1;
    if (purchase_date !== undefined) updateData.purchase_date = purchase_date && purchase_date.trim() ? purchase_date.trim() : null;

    if (
      updateData.quantity != null &&
      (updateData.quantity < 1 || !Number.isInteger(updateData.quantity))
    ) {
      return NextResponse.json(
        { error: "Количество должно быть целым числом не менее 1" },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }

    const { data, error } = await supabase
      .from("items")
      .update(updateData)
      .eq("id", itemId)
      .eq("tenant_id", tenantId)
      .select()
      .single();

    if (error) {
      return NextResponse.json(
        { error: error.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    try {
      await enqueueSearchIndexJob(supabase, {
        tenantId,
        entityType: "item",
        entityId: itemId,
      });
    } catch (error) {
      logError("Ошибка постановки вещи в очередь индексации после обновления:", error);
    }

    return NextResponse.json({ data });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка обновления вещи:",
      defaultMessage: "Произошла ошибка при обновлении вещи",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { requireIdParam } from "@/lib/shared/api/require-id-param";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import type { Transition } from "@/types/entity";

type TransitionRow = {
  id: number;
  created_at: string;
  item_id?: number | null;
  container_id?: number | null;
  place_id?: number | null;
  destination_type: Transition["destination_type"];
  destination_id: number | null;
};

type NamedRow = {
  id: number;
  name: string | null;
};

type FurnitureRow = NamedRow & {
  room_id: number | null;
};

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const supabase = await createClient();
    const idResult = await requireIdParam(params, { entityLabel: "вещи" });
    if (idResult instanceof NextResponse) return idResult;
    const itemId = idResult.id;

    // Загружаем все transitions для этой вещи
    const { data: transitionsData, error: transitionsError } = await supabase
      .from("transitions")
      .select("*")
      .eq("item_id", itemId)
      .order("created_at", { ascending: false });

    if (transitionsError) {
      return NextResponse.json(
        { error: transitionsError.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    // Загружаем названия мест назначения
    const placeIds = (transitionsData || [])
      .filter((t) => t.destination_type === "place" && t.destination_id)
      .map((t) => t.destination_id);
    const containerIds = (transitionsData || [])
      .filter((t) => t.destination_type === "container" && t.destination_id)
      .map((t) => t.destination_id);
    const roomIds = (transitionsData || [])
      .filter((t) => t.destination_type === "room" && t.destination_id)
      .map((t) => t.destination_id);
    const furnitureIds = (transitionsData || [])
      .filter((t) => t.destination_type === "furniture" && t.destination_id)
      .map((t) => t.destination_id);

    // Сначала загружаем контейнеры, чтобы получить их transitions и узнать их иерархию
    const containersData = containerIds.length > 0
      ? await supabase
          .from("containers")
          .select("id, name")
          .in("id", containerIds)
          .is("deleted_at", null)
      : { data: [] };

    const containersMap = new Map(
      (containersData.data || []).map((c) => [c.id, c.name])
    );

    // Получаем transitions для контейнеров, чтобы узнать их места
    const allContainerIds = Array.from(containersMap.keys());
    const { data: containersTransitionsData } = allContainerIds.length > 0
      ? await supabase
          .from("transitions")
          .select("*")
          .in("container_id", allContainerIds)
          .order("created_at", { ascending: false })
      : { data: [] };

    const lastContainerTransitions = new Map<number, TransitionRow>();
    (containersTransitionsData || []).forEach((t) => {
      if (t.container_id && !lastContainerTransitions.has(t.container_id)) {
        lastContainerTransitions.set(t.container_id, t);
      }
    });

    // Добавляем места из transitions контейнеров к списку мест
    const containerPlaceIds = Array.from(lastContainerTransitions.values())
      .filter((t) => t.destination_type === "place" && t.destination_id)
      .map((t) => t.destination_id);
    const containerRoomIds = Array.from(lastContainerTransitions.values())
      .filter((t) => t.destination_type === "room" && t.destination_id)
      .map((t) => t.destination_id);
    const containerFurnitureIds = Array.from(lastContainerTransitions.values())
      .filter((t) => t.destination_type === "furniture" && t.destination_id)
      .map((t) => t.destination_id);
    const allPlaceIds = Array.from(new Set([...placeIds, ...containerPlaceIds]));

    const { data: placeTransitionsData } = allPlaceIds.length > 0
      ? await supabase
          .from("transitions")
          .select("place_id, destination_type, destination_id")
          .in("place_id", allPlaceIds)
          .order("created_at", { ascending: false })
      : { data: [] };

    const lastPlaceTransitions = new Map<number, Partial<TransitionRow>>();
    (placeTransitionsData || []).forEach((t: Partial<TransitionRow>) => {
      if (t.place_id && !lastPlaceTransitions.has(t.place_id)) {
        lastPlaceTransitions.set(t.place_id, t);
      }
    });

    const placeFurnitureIds = Array.from(lastPlaceTransitions.values())
      .filter((t) => t.destination_type === "furniture" && t.destination_id)
      .map((t) => t.destination_id as number);
    const placeRoomIds = Array.from(lastPlaceTransitions.values())
      .filter((t) => t.destination_type === "room" && t.destination_id)
      .map((t) => t.destination_id as number);

    const allFurnitureIds = Array.from(
      new Set([...furnitureIds, ...containerFurnitureIds, ...placeFurnitureIds])
    );

    const [placesData, furnitureData] = await Promise.all([
      allPlaceIds.length > 0
        ? supabase
            .from("places")
            .select("id, name")
            .in("id", allPlaceIds)
            .is("deleted_at", null)
        : { data: [] },
      allFurnitureIds.length > 0
        ? supabase
            .from("furniture")
            .select("id, name, room_id")
            .in("id", allFurnitureIds)
            .is("deleted_at", null)
        : { data: [] },
    ]);

    const placesMap = new Map(
      (placesData.data || []).map((p: NamedRow) => [p.id, p.name])
    );
    const furnitureMap = new Map(
      (furnitureData.data || []).map((f: FurnitureRow) => [f.id, f])
    );

    const furnitureRoomIds = (furnitureData.data || [])
      .map((f: FurnitureRow) => f.room_id)
      .filter((id): id is number => id != null);
    const allRoomIds = Array.from(
      new Set([...roomIds, ...containerRoomIds, ...placeRoomIds, ...furnitureRoomIds])
    );

    const { data: roomsData } = allRoomIds.length > 0
      ? await supabase
          .from("rooms")
          .select("id, name")
          .in("id", allRoomIds)
          .is("deleted_at", null)
      : { data: [] };

    const roomsMap = new Map(
      (roomsData || []).map((r: NamedRow) => [r.id, r.name])
    );

    const resolveFurnitureHierarchy = (furnitureId: number) => {
      const furniture = furnitureMap.get(furnitureId);
      const roomName = furniture?.room_id != null
        ? roomsMap.get(furniture.room_id) || null
        : null;

      return {
        furniture_name: furniture?.name ?? null,
        room_name: roomName,
      };
    };

    const resolvePlaceHierarchy = (placeId: number) => {
      const hierarchy = {
        place_name: placesMap.get(placeId) || null,
        furniture_name: null as string | null,
        room_name: null as string | null,
      };
      const placeTransition = lastPlaceTransitions.get(placeId);

      if (!placeTransition?.destination_id) {
        return hierarchy;
      }

      if (placeTransition.destination_type === "furniture") {
        const furnitureHierarchy = resolveFurnitureHierarchy(placeTransition.destination_id);
        hierarchy.furniture_name = furnitureHierarchy.furniture_name;
        hierarchy.room_name = furnitureHierarchy.room_name;
        return hierarchy;
      }

      if (placeTransition.destination_type === "room") {
        hierarchy.room_name = roomsMap.get(placeTransition.destination_id) || null;
      }

      return hierarchy;
    };

    // Формируем transitions с названиями
    const transitionsWithNames = (transitionsData || []).map((t): Transition => {
      const transition: Transition = {
        id: t.id,
        created_at: t.created_at,
        destination_type: t.destination_type,
        destination_id: t.destination_id,
      };

      if (t.destination_type === "place" && t.destination_id) {
        transition.destination_name = placesMap.get(t.destination_id) || null;
        const placeHierarchy = resolvePlaceHierarchy(t.destination_id);
        transition.furniture_name = placeHierarchy.furniture_name;
        transition.room_name = placeHierarchy.room_name;
      } else if (t.destination_type === "container" && t.destination_id) {
        transition.destination_name = containersMap.get(t.destination_id) || null;
        const containerTransition = lastContainerTransitions.get(t.destination_id);
        if (containerTransition) {
          if (containerTransition.destination_type === "place" && containerTransition.destination_id) {
            const placeHierarchy = resolvePlaceHierarchy(containerTransition.destination_id);
            transition.place_name = placeHierarchy.place_name;
            transition.furniture_name = placeHierarchy.furniture_name;
            transition.room_name = placeHierarchy.room_name;
          } else if (containerTransition.destination_type === "furniture" && containerTransition.destination_id) {
            const furnitureHierarchy = resolveFurnitureHierarchy(containerTransition.destination_id);
            transition.furniture_name = furnitureHierarchy.furniture_name;
            transition.room_name = furnitureHierarchy.room_name;
          } else if (containerTransition.destination_type === "room" && containerTransition.destination_id) {
            transition.room_name = roomsMap.get(containerTransition.destination_id) || null;
          }
        }
      } else if (t.destination_type === "room" && t.destination_id) {
        transition.destination_name = roomsMap.get(t.destination_id) || null;
      } else if (t.destination_type === "furniture" && t.destination_id) {
        const furnitureHierarchy = resolveFurnitureHierarchy(t.destination_id);
        transition.destination_name = furnitureHierarchy.furniture_name;
        transition.room_name = furnitureHierarchy.room_name;
      }

      return transition;
    });

    return NextResponse.json({
      data: transitionsWithNames,
    });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка загрузки transitions вещи:",
      defaultMessage: "Произошла ошибка при загрузке transitions",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { normalizeSortParams } from "@/lib/shared/api/list-params";
import { validateItemMoney } from "@/lib/shared/api/validate-item-money";
import { insertEntityWithTransition } from "@/lib/shared/api/insert-entity-with-transition";
import { getItemsWithRoomRpc } from "@/lib/entities/api";
import {
  mapItemsRpcToItems,
  type ItemsRpcRow,
} from "@/lib/entities/helpers/map-items-rpc";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { parseOptionalInt } from "@/lib/shared/api/parse-optional-int";
import { validateDestinationType } from "@/lib/shared/api/validate-destination-type";
import { enqueueSearchIndexJob } from "@/lib/shared/api/search-index-queue";
import { logError } from "@/lib/shared/logger";

/**
 * Retrieve a paginated, optionally filtered and sorted list of items including each item's last known location and the total matching count.
 *
 * Expects query parameters: `query`, `showDeleted`, `page`, `limit`, `locationType`, `roomId`, `hasPhoto`, `sortBy`, and `sortDirection`. Requires an authenticated user; responds with 401 if not authenticated.
 *
 * @param request - Incoming NextRequest containing the query parameters described above
 * @returns An object with `data` and `totalCount`:
 *  - `data`: an array of items where each item includes `id`, `name`, `item_type_id`, optional `item_type` (with `name`), `created_at`, `deleted_at`, `photo_url`, `room_id`, `room_name`, and `last_location` (object with `destination_type`, `destination_id`, `moved_at`, `room_name` or `null` if no location).
 *  - `totalCount`: the total number of items matching the query
 */
export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const supabase = await createClient();
    const { searchParams } = new URL(request.url);
    const query = searchParams.get("query") || null;
    const showDeleted = searchParams.get("showDeleted") === "true";
    const page = parseInt(searchParams.get("page") || "1", 10);
    const limit = parseInt(searchParams.get("limit") || "20", 10);
    const entityTypeId = parseOptionalInt(searchParams.get("entityTypeId"));
    const locationType = searchParams.get("locationType") || null;
    const roomId = parseOptionalInt(searchParams.get("roomId"));
    const placeId = parseOptionalInt(searchParams.get("placeId"));
    const containerId = parseOptionalInt(searchParams.get("containerId"));
    const furnitureId = parseOptionalInt(searchParams.get("furnitureId"));
    const hasPhoto = searchParams.get("hasPhoto") === "true" ? true : searchParams.get("hasPhoto") === "false" ? false : null;
    const { sortBy, sortDirection } = normalizeSortParams(
      searchParams.get("sortBy"),
      searchParams.get("sortDirection")
    );

    const from = (page - 1) * limit;

    const { data: itemsData, error: itemsError } = await getItemsWithRoomRpc(supabase, {
      search_query: query?.trim() || null,
      show_deleted: showDeleted,
      page_limit: limit,
      page_offset: from,
      location_type: locationType,
      room_id: roomId,
      place_id: placeId,
      container_id: containerId,
      furniture_id: furnitureId,
      filter_item_type_id: entityTypeId,
      has_photo: hasPhoto,
      sort_by: sortBy,
      sort_direction: sortDirection,
      filter_tenant_id: tenantId,
    });

    if (itemsError) {
      return NextResponse.json(
        { error: itemsError.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    if (!itemsData || itemsData.length === 0) {
      return NextResponse.json({
        data: [],
        totalCount: 0,
      });
    }

    const totalCount = itemsData[0]?.total_count ?? 0;
    const items = mapItemsRpcToItems(itemsData as ItemsRpcRow[]);

    return NextResponse.json({
      data: items,
      totalCount,
    });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка загрузки списка вещей:",
      defaultMessage: "Произошла ошибка при загрузке данных",
    });
  }
}

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const supabase = await createClient();
    const body = await request.json();
    const {
      name,
      photo_url,
      destination_type,
      destination_id,
      item_type_id,
      quantity,
      purchase_date,
    } = body;

    const moneyValidation = validateItemMoney(body);
    if (moneyValidation instanceof NextResponse) return moneyValidation;

    const insertItemData: {
      name: string | null;
      photo_url: string | null;
      item_type_id: number | null;
      price_amount: number | null;
      price_currency: string | null;
      current_value_amount: number | null;
      current_value_currency: string | null;
      quantity: number | null;
      purchase_date: string | null;
      tenant_id: number;
    } = {
      name: name?.trim() || null,
      photo_url: photo_url || null,
      item_type_id: item_type_id != null ? (Number(item_type_id) || null) : null,
      price_amount: moneyValidation.price_amount,
      price_currency: moneyValidation.price_currency,
      current_value_amount: moneyValidation.current_value_amount,
      current_value_currency: moneyValidation.current_value_currency,
      quantity: quantity != null && quantity !== "" ? Number(quantity) : 1,
      purchase_date: purchase_date && purchase_date.trim() ? purchase_date.trim() : null,
      tenant_id: tenantId,
    };

    if (
      insertItemData.quantity != null &&
      (insertItemData.quantity < 1 || !Number.isInteger(insertItemData.quantity))
    ) {
      return NextResponse.json(
        { error: "Количество должно быть целым числом не менее 1" },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }

    const validatedDestType = validateDestinationType(destination_type);
    if (validatedDestType instanceof NextResponse) return validatedDestType;

    const transitionPayload =
      validatedDestType && destination_id
        ? {
            destination_type: validatedDestType,
            destination_id: parseInt(destination_id, 10),
            tenant_id: tenantId,
          }
        : null;

    const result = await insertEntityWithTransition({
      supabase,
      table: "items",
      insertData: insertItemData,
      transitionPayload,
    });

    if (result.error || !result.data) {
      return NextResponse.json(
        { error: result.error || "Не удалось создать вещь" },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    try {
      await enqueueSearchIndexJob(supabase, {
        tenantId,
        entityType: "item",
        entityId: result.data.id,
      });
    } catch (error) {
      logError("Ошибка постановки вещи в очередь индексации после создания:", error);
    }

    return NextResponse.json({ data: result.data });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка создания вещи:",
      defaultMessage: "Произошла ошибка при создании вещи",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { setTenantCookieInResponse } from "@/lib/tenants/server";
import { requireAuth } from "@/lib/shared/api/require-auth";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (auth instanceof NextResponse) return auth;
    const { user } = auth;

    const body = await request.json();
    const raw = body?.tenantId;
    const tenantIdNum =
      typeof raw === "number"
        ? raw
        : typeof raw === "string"
          ? parseInt(raw, 10)
          : NaN;
    if (!Number.isInteger(tenantIdNum) || tenantIdNum <= 0) {
      return NextResponse.json(
        { error: "tenantId required" },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }
    const tenantId = tenantIdNum;

    const supabase = await createClient();
    const { data, error } = await supabase
      .from("tenant_memberships")
      .select("id")
      .eq("tenant_id", tenantId)
      .eq("user_id", user.id)
      .single();

    if (error || !data) {
      return NextResponse.json(
        { error: "Тенант не найден или нет доступа" },
        { status: HTTP_STATUS.FORBIDDEN }
      );
    }

    const res = NextResponse.json({ success: true });
    res.headers.set(
      "Set-Cookie",
      setTenantCookieInResponse(tenantId)
    );
    return res;
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка переключения тенанта:",
      defaultMessage: "Произошла ошибка при переключении тенанта",
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/shared/supabase/server";
import { requireAuthAndTenant } from "@/lib/shared/api/require-auth";
import { parseId } from "@/lib/shared/api/parse-id";
import { apiErrorResponse } from "@/lib/shared/api/api-error-response";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { PLACE_DESTINATION_FURNITURE_ONLY } from "@/lib/places/validation-messages";
import { transitionBodySchema } from "@/lib/shared/api/schemas/transition-body";
import type { DestinationType } from "@/types/entity";

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuthAndTenant(request);
    if (auth instanceof NextResponse) return auth;
    const { tenantId } = auth;
    const supabase = await createClient();
    const body = await request.json();

    const parsed = transitionBodySchema.safeParse(body);
    if (!parsed.success) {
      const issues = "issues" in parsed.error ? parsed.error.issues : [];
      const first = Array.isArray(issues) ? issues[0] : null;
      const message =
        first && typeof first === "object" && "message" in first
          ? String(first.message)
          : String(parsed.error.message ?? "Неверный формат тела запроса");
      return NextResponse.json({ error: message }, { status: HTTP_STATUS.BAD_REQUEST });
    }

    const { item_id, place_id, container_id, destination_type, destination_id } = parsed.data;
    const validatedDestType = destination_type;

    if (place_id && validatedDestType !== "furniture") {
      return NextResponse.json(
        { error: PLACE_DESTINATION_FURNITURE_ONLY },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }

    const destIdResult = parseId(String(destination_id), { entityLabel: "назначения" });
    if (destIdResult instanceof NextResponse) return destIdResult;

    const parseOptionalId = (value: unknown): number | undefined => {
      if (value == null || value === "") return undefined;
      const id = typeof value === "number" ? value : parseInt(String(value), 10);
      return Number.isNaN(id) || id <= 0 ? undefined : id;
    };

    const transitionData: {
      destination_type: DestinationType;
      destination_id: number;
      tenant_id: number;
      item_id?: number;
      place_id?: number;
      container_id?: number;
    } = {
      destination_type: validatedDestType,
      destination_id: destIdResult.id,
      tenant_id: tenantId,
    };

    const itemId = parseOptionalId(item_id);
    const placeId = parseOptionalId(place_id);
    const containerId = parseOptionalId(container_id);
    if (item_id != null && item_id !== "" && itemId == null) {
      return NextResponse.json({ error: "Некорректный item_id" }, { status: HTTP_STATUS.BAD_REQUEST });
    }
    if (place_id != null && place_id !== "" && placeId == null) {
      return NextResponse.json({ error: "Некорректный place_id" }, { status: HTTP_STATUS.BAD_REQUEST });
    }
    if (container_id != null && container_id !== "" && containerId == null) {
      return NextResponse.json({ error: "Некорректный container_id" }, { status: HTTP_STATUS.BAD_REQUEST });
    }
    if (itemId == null && placeId == null && containerId == null) {
      return NextResponse.json(
        { error: "Необходим хотя бы один из: item_id, place_id, container_id" },
        { status: HTTP_STATUS.BAD_REQUEST }
      );
    }
    if (itemId != null) transitionData.item_id = itemId;
    if (placeId != null) transitionData.place_id = placeId;
    if (containerId != null) transitionData.container_id = containerId;

    const { data, error } = await supabase
      .from("transitions")
      .insert(transitionData)
      .select()
      .single();

    if (error) {
      return NextResponse.json(
        { error: error.message },
        { status: HTTP_STATUS.INTERNAL_SERVER_ERROR }
      );
    }

    return NextResponse.json({ data });
  } catch (error) {
    return apiErrorResponse(error, {
      context: "Ошибка создания transition:",
      defaultMessage: "Произошла ошибка при создании transition",
    });
  }
}

"use client";

import { useEffect, useRef, useState, useCallback, useId } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Loader2 } from "lucide-react";
import { parseEntityQrPayload, type EntityQrPayload } from "@/lib/entities/helpers/qr-code";

const FPS = 10;
const EAN_13_REGEX = /^\d{13}$/;

type ScannerMode = "qr" | "barcode";

interface ScannerBaseProps {
  open: boolean;
  onClose: () => void;
  title: string;
  scanningHint: string;
  mode: ScannerMode;
}

interface QRScannerProps {
  open: boolean;
  onClose: () => void;
  onScanSuccess: (result: EntityQrPayload) => void;
}

interface BarcodeScannerProps {
  open: boolean;
  onClose: () => void;
  onScanSuccess: (barcode: string) => void;
}

function ScannerBase({
  open,
  onClose,
  title,
  scanningHint,
  mode,
  onScanSuccess,
}: ScannerBaseProps & {
  onScanSuccess: (value: string | EntityQrPayload) => void;
}) {
  const [mounted, setMounted] = useState(false);
  const scannerRef = useRef<
    { clear: () => void | Promise<void>; stop: () => Promise<void> } | null
  >(null);
  const isScanningRef = useRef(false);
  const isInitializingRef = useRef(false);
  const initAttemptRef = useRef(0);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const scanSuccessCallbackRef = useRef(onScanSuccess);
  const elementId = useId().replace(/:/g, "-");

  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);

  useEffect(() => {
    scanSuccessCallbackRef.current = onScanSuccess;
  }, [onScanSuccess]);

  const stopScanner = useCallback(async () => {
    if (scannerRef.current) {
      try {
        if (isScanningRef.current) {
          await scannerRef.current.stop().catch(() => { });
        }
        await Promise.resolve(scannerRef.current.clear()).catch(() => { });
      } catch (err) {
        if (process.env.NODE_ENV === "development") console.debug("Error stopping scanner:", err);
      }
      isScanningRef.current = false;
      setIsScanning(false);
      scannerRef.current = null;
    }
    isInitializingRef.current = false;

    const element = document.getElementById(elementId);
    if (element) {
      element.innerHTML = "";
      while (element.firstChild) {
        element.removeChild(element.firstChild);
      }
    }
  }, [elementId]);

  useEffect(() => {
    if (!open) {
      stopScanner();
      initAttemptRef.current = 0;
      setError(null);
      setIsScanning(false);
      return;
    }

    if (typeof window === "undefined") return;

    const currentAttempt = ++initAttemptRef.current;
    if (isInitializingRef.current || isScanningRef.current) return;

    const initScanner = async () => {
      if (currentAttempt !== initAttemptRef.current) return;

      if (scannerRef.current) {
        await stopScanner();
        await new Promise((resolve) => setTimeout(resolve, 300));
      }

      if (currentAttempt !== initAttemptRef.current) return;

      isInitializingRef.current = true;
      setError(null);

      try {
        await new Promise((resolve) => setTimeout(resolve, 100));

        const element = document.getElementById(elementId);
        if (!element) {
          throw new Error("Элемент для сканера не найден в DOM");
        }

        element.innerHTML = "";
        while (element.firstChild) {
          element.removeChild(element.firstChild);
        }

        if (currentAttempt !== initAttemptRef.current) {
          isInitializingRef.current = false;
          return;
        }

        const { Html5Qrcode, Html5QrcodeSupportedFormats } = await import(
          "html5-qrcode"
        );

        const Html5QrcodeCtor =
          typeof Html5Qrcode === "function"
            ? Html5Qrcode
            : (Html5Qrcode as { Html5Qrcode?: typeof Html5Qrcode }).Html5Qrcode;

        if (!Html5QrcodeCtor) {
          throw new Error("Не удалось найти Html5Qrcode в модуле.");
        }

        const formats =
          mode === "qr"
            ? [Html5QrcodeSupportedFormats.QR_CODE]
            : [Html5QrcodeSupportedFormats.EAN_13];

        const scanner = new Html5QrcodeCtor(elementId, {
          verbose: false,
          formatsToSupport: formats,
        });

        scannerRef.current = scanner;

        const devices = await Html5QrcodeCtor.getCameras();
        if (devices.length === 0) {
          setError("Камера не найдена.");
          isInitializingRef.current = false;
          return;
        }

        const backCamera = devices.find(
          (d) =>
            d.label?.toLowerCase().includes("back") ||
            d.label?.toLowerCase().includes("rear") ||
            d.label?.toLowerCase().includes("environment"),
        );
        const selectedCamera = backCamera || devices[0];
        if (!selectedCamera?.id) {
          throw new Error("Не удалось выбрать камеру");
        }

        await scanner.start(
          selectedCamera.id,
          {
            fps: FPS,
            aspectRatio: 1.0,
            disableFlip: false,
          },
          (decodedText: string) => {
            const trimmed = decodedText.trim();
            if (mode === "qr") {
              const parsed = parseEntityQrPayload(trimmed);
              if (parsed) {
                scanSuccessCallbackRef.current(parsed);
                stopScanner();
              } else {
                setError(
                  "Неверный формат QR-кода. Ожидается формат этикетки: тип:id (например, item:123).",
                );
              }
            } else {
              if (EAN_13_REGEX.test(trimmed)) {
                scanSuccessCallbackRef.current(trimmed);
                stopScanner();
              } else {
                setError(
                  "Распознан неверный формат. Ожидается штрихкод EAN-13 (13 цифр).",
                );
              }
            }
          },
          (errorMessage: string) => {
            if (
              errorMessage &&
              !errorMessage.includes("NotFoundException") &&
              !errorMessage.includes("No QR code found") &&
              process.env.NODE_ENV === "development"
            ) {
              console.debug("Scanner error:", errorMessage);
            }
          },
        );

        if (currentAttempt !== initAttemptRef.current) {
          await stopScanner();
          return;
        }

        isScanningRef.current = true;
        setIsScanning(true);
        setError(null);
        isInitializingRef.current = false;
      } catch (err) {
        if (currentAttempt !== initAttemptRef.current) return;

        console.error("Scanner init error:", err);
        setError(
          err instanceof Error ? err.message : "Не удалось инициализировать сканер",
        );
        isScanningRef.current = false;
        setIsScanning(false);
        isInitializingRef.current = false;
      }
    };

    initScanner();

    return () => {
      initAttemptRef.current++;
      stopScanner();
    };
  }, [open, elementId, mode, stopScanner]);

  const handleClose = useCallback(() => {
    onClose();
    stopScanner().catch(() => { });
  }, [stopScanner, onClose]);

  if (!mounted) return null;

  return (
    <Dialog
      open={open}
      onOpenChange={(newOpen) => {
        if (!newOpen) handleClose();
      }}
    >
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
        </DialogHeader>

        <div
          id={elementId}
          className="relative z-0 w-full overflow-hidden rounded-lg border aspect-square bg-muted [&_video]:z-[1] [&_video]:pointer-events-auto [&_canvas]:z-[1] [&_canvas]:pointer-events-auto"
          onClick={(e) => e.stopPropagation()}
        />

        {error && (
          <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
            {error}
          </div>
        )}

        {!isScanning && !error && (
          <div className="flex items-center justify-center gap-2 text-sm text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" />
            <span>Инициализация камеры...</span>
          </div>
        )}

        {isScanning && (
          <div className="text-center text-sm text-muted-foreground">
            {scanningHint}
          </div>
        )}

        <DialogFooter>
          <DialogClose render={<Button variant="outline" />}>
            Отмена
          </DialogClose>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function QRScanner({
  open,
  onClose,
  onScanSuccess,
}: QRScannerProps) {
  return (
    <ScannerBase
      open={open}
      onClose={onClose}
      title="Сканирование QR-кода"
      scanningHint="Наведите камеру на QR-код"
      mode="qr"
      onScanSuccess={onScanSuccess as (value: string | EntityQrPayload) => void}
    />
  );
}

export function BarcodeScanner({
  open,
  onClose,
  onScanSuccess,
}: BarcodeScannerProps) {
  return (
    <ScannerBase
      open={open}
      onClose={onClose}
      title="Сканирование штрихкода"
      scanningHint="Наведите камеру на штрихкод EAN-13"
      mode="barcode"
      onScanSuccess={onScanSuccess as (value: string | EntityQrPayload) => void}
    />
  );
}

import { ReactNode } from "react";
import { EntityDetailError } from "./entity-detail-error";
import { EntityDetailSkeleton } from "./entity-detail-skeleton";

export interface EntityDetailLayoutProps {
  isLoading: boolean;
  isInvalidId?: boolean;
  error?: string | null;
  entityName: string;
  hasEntity: boolean;

  header: ReactNode;
  relatedLinks?: ReactNode;

  editForm: ReactNode;
  imageCard?: ReactNode;

  contentBlocks?: ReactNode;
  modals?: ReactNode;
}

export function EntityDetailLayout({
  isLoading,
  isInvalidId,
  error,
  entityName,
  hasEntity,
  header,
  relatedLinks,
  editForm,
  imageCard,
  contentBlocks,
  modals,
}: EntityDetailLayoutProps) {
  if (isInvalidId) {
    return (
      <EntityDetailError
        error={`Некорректный ID: ${entityName}`}
        entityName={entityName}
      />
    );
  }

  if (error && !isLoading) {
    return <EntityDetailError error={error} entityName={entityName} />;
  }

  if (!isLoading && !hasEntity) {
    return null;
  }

  return (
    <div className="flex flex-col gap-4">
      {header}
      {hasEntity && relatedLinks}

      {isLoading ? (
        <EntityDetailSkeleton />
      ) : hasEntity ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="flex flex-col gap-6">
            {editForm}
            {imageCard}
          </div>
          {contentBlocks && (
            <div className="flex flex-col gap-6">
              {contentBlocks}
            </div>
          )}
        </div>
      ) : null}

      {modals}
    </div>
  );
}

"use client";

import * as React from "react";
import { useState, useCallback } from "react";
import { LayoutGrid, Container as ContainerIcon, DoorOpen, Sofa, QrCode } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@/components/ui/combobox";
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field";
import { Skeleton } from "@/components/ui/skeleton";
import { useRooms } from "@/lib/rooms/hooks/use-rooms";
import { usePlaces } from "@/lib/places/hooks/use-places";
import { useContainers } from "@/lib/containers/hooks/use-containers";
import { useFurniture } from "@/lib/furniture/hooks/use-furniture";
import type { Container, Place, Room, Furniture, DestinationType } from "@/types/entity";
import { QRScanner } from "@/components/common/scanner";
import type { EntityQrPayload } from "@/lib/entities/helpers/qr-code";
import { toast } from "sonner";

interface LocationComboboxProps {
  destinationType: DestinationType | null;
  selectedDestinationId: string;
  onDestinationTypeChange: (type: DestinationType | null) => void;
  onDestinationIdChange: (id: string) => void;
  disabled?: boolean;
  /** When set, only these destination types are shown (e.g. for move form). */
  allowedTypes?: DestinationType[];
  /** When moving a container, exclude this id from container list. */
  excludeContainerId?: number;
  label?: string;
  id?: string;
  /** Показывать кнопку сканирования QR для быстрого выбора места. По умолчанию true. */
  showQrScan?: boolean;
}

const VALID_LOCATION_QR_TYPES: DestinationType[] = [
  "place",
  "room",
  "container",
  "furniture",
];

const LocationCombobox = ({
  destinationType,
  selectedDestinationId,
  onDestinationTypeChange,
  onDestinationIdChange,
  disabled = false,
  allowedTypes,
  excludeContainerId,
  label = "Местоположение (необязательно)",
  id = "location-combobox",
  showQrScan = true,
}: LocationComboboxProps) => {
  const [scanLocationQrOpen, setScanLocationQrOpen] = useState(false);

  const handleLocationQrScan = useCallback(
    (payload: EntityQrPayload) => {
      if (VALID_LOCATION_QR_TYPES.includes(payload.type as DestinationType)) {
        onDestinationTypeChange(payload.type as DestinationType);
        onDestinationIdChange(String(payload.id));
        setScanLocationQrOpen(false);
        const typeLabel =
          payload.type === "place"
            ? "Место"
            : payload.type === "room"
              ? "Помещение"
              : payload.type === "container"
                ? "Контейнер"
                : "Мебель";
        toast.success("Место задано по QR-коду", {
          description: `${typeLabel} #${payload.id}`,
        });
      } else {
        toast.error("Не подходит для местоположения", {
          description:
            "Отсканируйте QR-код места, помещения, контейнера или мебели",
        });
      }
    },
    [onDestinationTypeChange, onDestinationIdChange]
  );

  const { rooms, isLoading: isLoadingRooms } = useRooms();
  const { places, isLoading: isLoadingPlaces } = usePlaces();
  const { containers, isLoading: isLoadingContainers } = useContainers();
  const { furniture, isLoading: isLoadingFurniture } = useFurniture();

  const loadingByType: Record<DestinationType, boolean> = {
    container: isLoadingContainers,
    place: isLoadingPlaces,
    room: isLoadingRooms,
    furniture: isLoadingFurniture,
  };
  const isLoading = destinationType ? loadingByType[destinationType] : false;

  const dataByType: Record<DestinationType, (Room | Place | Container | Furniture)[]> = {
    container: containers,
    place: places,
    room: rooms,
    furniture,
  };
  const rawDestinations = destinationType ? dataByType[destinationType] : [];
  const destinations =
    destinationType === "container" && excludeContainerId != null
      ? rawDestinations.filter((c) => (c as { id: number }).id !== excludeContainerId)
      : rawDestinations;

  const labelByType: Record<DestinationType, string> = {
    container: "контейнер",
    place: "местоположение",
    room: "помещение",
    furniture: "мебель",
  };
  const destinationLabel = destinationType ? labelByType[destinationType] : "";

  const buttonOrderOptions = [
    { type: "room" as const, label: "Помещение", icon: DoorOpen },
    { type: "place" as const, label: "Место", icon: LayoutGrid },
    { type: "container" as const, label: "Контейнер", icon: ContainerIcon },
    { type: "furniture" as const, label: "Мебель", icon: Sofa },
  ];
  const buttonOrder = allowedTypes?.length
    ? buttonOrderOptions.filter((b) => allowedTypes.includes(b.type))
    : buttonOrderOptions;

  const items = React.useMemo(() => {
    const fallbackByType: Record<DestinationType, string> = {
      container: "Контейнер",
      place: "Место",
      room: "Помещение",
      furniture: "Мебель",
    };
    const fallback = destinationType ? fallbackByType[destinationType] : "Объект";
    return destinations.map((dest) => {
      const displayName = dest.name || `${fallback} #${dest.id}`;
      const typeName =
        destinationType === "container" || destinationType === "place"
          ? (dest as Container | Place).entity_type?.name
          : destinationType === "furniture"
            ? (dest as Furniture).furniture_type?.name
            : null;
      const label = typeName ? `${displayName} (${typeName})` : displayName;
      return { value: dest.id.toString(), label };
    });
  }, [destinations, destinationType]);

  const selectedItem =
    items.find((i) => i.value === selectedDestinationId) ?? null;

  const handleValueChange = (item: { value: string; label: string } | null) => {
    onDestinationIdChange(item?.value ?? "");
  };

  return (
    <FieldGroup>
      <Field>
        <FieldLabel>{label}</FieldLabel>
        <div className="flex flex-wrap gap-2">
          {buttonOrder.map(({ type, label: btnLabel, icon: Icon }) => (
            <Button
              key={type}
              type="button"
              variant={destinationType === type ? "default" : "outline"}
              size="sm"
              className="flex-1"
              onClick={() => {
                onDestinationTypeChange(type);
                onDestinationIdChange("");
              }}
              disabled={disabled}
            >
              <Icon className="mr-2 h-4 w-4" />
              {btnLabel}
            </Button>
          ))}
          {showQrScan && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setScanLocationQrOpen(true)}
              disabled={disabled}
              aria-label="Сканировать QR-код места"
            >
              <QrCode className="mr-2 h-4 w-4" />
              Сканировать QR
            </Button>
          )}
        </div>
      </Field>

      {destinationType && (
        <Field>
          <FieldLabel htmlFor={`${id}-combobox`}>
            {`Выберите ${destinationLabel}`}
          </FieldLabel>

          <Combobox
            value={selectedItem}
            items={items}
            onValueChange={handleValueChange}
            disabled={disabled || (isLoading ? false : destinations.length === 0)}
          >
            {isLoading ? (
              <Skeleton className="h-8 w-full" />
            ) : (
              <ComboboxInput
                id={`${id}-combobox`}
                placeholder={`Поиск ${destinationLabel}...`}
              />
            )}
            <ComboboxContent>
              <ComboboxEmpty>
                {destinationType === "container"
                  ? "Контейнеры не найдены"
                  : destinationType === "place"
                    ? "Местоположения не найдены"
                    : destinationType === "furniture"
                      ? "Мебель не найдена"
                      : "Помещения не найдены"}
              </ComboboxEmpty>
              <ComboboxList>
                {(item: { value: string; label: string }) => (
                  <ComboboxItem key={item.value} value={item}>
                    {item.label}
                  </ComboboxItem>
                )}
              </ComboboxList>
            </ComboboxContent>
          </Combobox>
            {!isLoading && destinations.length === 0 && (
            <p className="text-xs text-muted-foreground">
              {destinationType === "container"
                ? "Контейнеры не найдены"
                : destinationType === "place"
                  ? "Местоположения не найдены"
                  : destinationType === "furniture"
                    ? "Мебель не найдена"
                    : "Помещения не найдены"}
            </p>
          )}
        </Field>
      )}
      <QRScanner
        open={scanLocationQrOpen}
        onClose={() => setScanLocationQrOpen(false)}
        onScanSuccess={handleLocationQrScan}
      />
    </FieldGroup>
  );
};

export default LocationCombobox;

"use client";

import { useState } from "react";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Field, FieldLabel } from "@/components/ui/field";
import {
  SUPPORTED_CURRENCIES,
  formatAmountDisplay,
  minorUnitsToDisplayString,
  parseMoneyToMinorUnits,
} from "@/lib/shared/money";
import { cn } from "@/lib/utils";

const DEFAULT_CURRENCY = "RUB";

export interface PriceValue {
  amount: number;
  currency: string;
}

interface PriceInputProps {
  value: PriceValue | null;
  onChange: (value: PriceValue | null) => void;
  id?: string;
  label?: string;
  disabled?: boolean;
  className?: string;
}

export function PriceInput({
  value,
  onChange,
  id = "price",
  label = "Цена (необязательно)",
  disabled = false,
  className,
}: PriceInputProps) {
  const [pendingCurrency, setPendingCurrency] = useState(DEFAULT_CURRENCY);
  const [isFocused, setIsFocused] = useState(false);
  const [localInput, setLocalInput] = useState("");
  const hasPrice = value != null;
  const currency = hasPrice ? value.currency : pendingCurrency;

  const displayValue = isFocused
    ? localInput
    : hasPrice
      ? formatAmountDisplay(value.amount, value.currency)
      : "";

  const handleFocus = () => {
    setIsFocused(true);
    setLocalInput(
      hasPrice ? minorUnitsToDisplayString(value.amount, value.currency) : ""
    );
  };

  const commitValue = () => {
    if (!isFocused) return;
    setIsFocused(false);
    const raw = localInput.trim();
    if (!raw) {
      setPendingCurrency(currency);
      onChange(null);
      setLocalInput("");
      return;
    }
    const parsed = parseMoneyToMinorUnits(raw, currency);
    if (parsed !== null) {
      onChange({ amount: parsed, currency });
    }
    setLocalInput("");
  };

  const handleBlur = () => commitValue();

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") commitValue();
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalInput(e.target.value);
  };

  const handleCurrencyChange = (newCurrency: string | null) => {
    const currencyVal = newCurrency ?? DEFAULT_CURRENCY;
    setPendingCurrency(currencyVal);
    const raw = isFocused ? localInput : displayValue;
    if (!raw.trim()) {
      onChange(null);
      return;
    }
    const parsed = parseMoneyToMinorUnits(raw, currencyVal);
    if (parsed !== null) {
      onChange({ amount: parsed, currency: currencyVal });
    } else {
      onChange({ amount: 0, currency: currencyVal });
    }
  };

  return (
    <Field className={cn(className)}>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <div className="flex gap-2">
        <Input
          id={id}
          type="text"
          inputMode="decimal"
          placeholder="0"
          value={displayValue}
          onChange={handleAmountChange}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          disabled={disabled}
          className="flex-1"
        />
        <Select
          value={currency}
          onValueChange={handleCurrencyChange}
          disabled={disabled}
        >
          <SelectTrigger className="w-[120px]">
            <SelectValue placeholder="Валюта" />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              {SUPPORTED_CURRENCIES.map((c) => (
                <SelectItem key={c.code} value={c.code}>
                  {c.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
      </div>
    </Field>
  );
}

"use client";

import { Field, FieldLabel, FieldSet } from "@/components/ui/field";
import { EntityFiltersShell } from "./entity-filters-shell";
import { YesNoAllFilter } from "./yes-no-all-filter";
import { LocationTypeSelect } from "@/components/fields/location-type-select";
import { RoomsSelect } from "@/components/fields/rooms-select";
import { BuildingsSelect } from "@/components/fields/buildings-select";
import { FurnitureSelect } from "@/components/fields/furniture-select";
import {
  Combobox,
  ComboboxContent,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@/components/ui/combobox";
import { Skeleton } from "@/components/ui/skeleton";
import type { FilterFieldConfig, Filters } from "@/types/entity";
import { useEntityTypeFilterOptions } from "@/lib/entities/hooks/use-entity-type-filter-options";

/** Filter field config that has a key (excludes showDeleted). */
type FilterFieldWithKey = Exclude<FilterFieldConfig, { type: "showDeleted" }>;

export interface EntityFiltersPanelProps {
  fields: FilterFieldConfig[];
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

export function EntityFiltersPanel({
  fields,
  filters,
  onFiltersChange,
}: EntityFiltersPanelProps) {
  const showDeletedField = fields.find((f) => f.type === "showDeleted");
  const showDeletedLabel =
    showDeletedField?.type === "showDeleted"
      ? showDeletedField.label
      : "Показывать удалённые";

  const handleShowDeletedChange = (checked: boolean) => {
    onFiltersChange({ ...filters, showDeleted: checked });
  };

  const otherFields = fields.filter(
    (f): f is FilterFieldWithKey => f.type !== "showDeleted"
  );

  const renderFilterField = (field: FilterFieldWithKey) => {
    const value = (filters as Record<string, unknown>)[field.key];
    const setFilterValue = (v: string | number | boolean | null) =>
      onFiltersChange({
        ...filters,
        [field.key]: v === "all" || v == null ? null : v,
      });
    const setNumericValue = (v: string | null) =>
      onFiltersChange({
        ...filters,
        [field.key]:
          v === "all" || v == null ? null : parseInt(String(v), 10),
      });

    switch (field.type) {
      case "yesNoAll":
        return (
          <YesNoAllFilter
            key={field.key}
            label={field.label}
            value={(value as boolean | null | undefined) ?? null}
            onChange={(v) => onFiltersChange({ ...filters, [field.key]: v })}
          />
        );
      case "locationType":
        return (
          <LocationTypeSelect
            key={field.key}
            value={(value as "all" | "room" | "place" | "container" | null | undefined) ?? null}
            onValueChange={(v) => setFilterValue(v === "all" ? null : v)}
          />
        );
      case "room":
        return (
          <RoomsSelect
            key={field.key}
            value={(value as number | null | undefined) ?? null}
            onValueChange={setNumericValue}
          />
        );
      case "building":
        return (
          <BuildingsSelect
            key={field.key}
            value={(value as number | null | undefined) ?? null}
            onValueChange={setNumericValue}
          />
        );
      case "furniture":
        return (
          <FurnitureSelect
            key={field.key}
            value={(value as number | null | undefined) ?? null}
            onValueChange={setNumericValue}
          />
        );
      case "entityType":
        return (
          <EntityTypeFilterField
            key={field.key}
            entityKind={field.entityKind}
            value={(value as number | null | undefined) ?? null}
            onValueChange={setNumericValue}
            label={
              field.entityKind === "item"
                ? "Категория"
                : field.entityKind === "place"
                ? "Тип места"
                : field.entityKind === "furniture"
                  ? "Тип мебели"
                  : "Тип контейнера"
            }
          />
        );
      default:
        return null;
    }
  };

  const fieldsContent = (
    <>{otherFields.map((field) => renderFilterField(field))}</>
  );

  return showDeletedField ? (
    <EntityFiltersShell
      showDeletedLabel={showDeletedLabel}
      showDeleted={filters.showDeleted}
      onShowDeletedChange={handleShowDeletedChange}
    >
      {fieldsContent}
    </EntityFiltersShell>
  ) : (
    <FieldSet>{fieldsContent}</FieldSet>
  );
}

interface EntityTypeFilterFieldProps {
  entityKind: "item" | "place" | "container" | "furniture";
  value: number | null | undefined;
  onValueChange: (value: string | null) => void;
  label: string;
}

function EntityTypeFilterField({
  entityKind,
  value,
  onValueChange,
  label,
}: EntityTypeFilterFieldProps) {
  const { options, isLoading } =
    useEntityTypeFilterOptions(entityKind);
  const selectedOption = options.find((option) => option.value === (value != null ? value.toString() : "all")) ?? null;

  return (
    <Field>
      <FieldLabel>{label}</FieldLabel>
      {isLoading ? (
        <Skeleton className="h-8 w-full" />
      ) : (
        <Combobox
          key={selectedOption ? `${entityKind}-${selectedOption.value}` : `${entityKind}-empty`}
          value={selectedOption}
          items={options}
          onValueChange={(option) => onValueChange(option?.value === "all" ? null : option?.value ?? null)}
        >
          <ComboboxInput placeholder={`Выберите ${label.toLowerCase()}...`} />
          <ComboboxContent>
            <ComboboxList>
              {(option: typeof options[number]) => (
                <ComboboxItem key={option.value} value={option}>
                  {option.label}
                </ComboboxItem>
              )}
            </ComboboxList>
          </ComboboxContent>
        </Combobox>
      )}
    </Field>
  );
}

