"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Loader2, ScanSearch, Search, PlusCircle, PackageSearch } from "lucide-react";
import { searchApiClient } from "@/lib/shared/api/search";
import { logError } from "@/lib/shared/logger";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { PageHeader } from "@/components/layout/page-header";
import { CameraCaptureDialog } from "@/components/common/camera-capture-dialog";
import { toast } from "sonner";
import type { SearchHit, SearchMode } from "@/lib/search/types";
import { SearchResultsSection } from "@/components/search/search-results-section";
import { SearchSessionBanner } from "@/components/search/search-session-banner";
import { SearchEmptyState } from "@/components/search/search-empty-state";
import { useAddItem } from "@/lib/app/contexts/add-item-context";

interface ActiveSearchSession {
  mode: SearchMode;
  previewUrl?: string | null;
  file?: File;
}

export function GlobalSearchPage() {
  const addItemContext = useAddItem();
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<SearchHit[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isPhotoSearchOpen, setIsPhotoSearchOpen] = useState(false);
  const [activeSession, setActiveSession] = useState<ActiveSearchSession | null>(null);
  const [totalCount, setTotalCount] = useState(0);
  const searchRequestIdRef = useRef(0);
  const isMountedRef = useRef(true);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const clearSearchSession = useCallback(() => {
    setSearchResults([]);
    setTotalCount(0);
    setActiveSession((prev) => {
      if (prev?.previewUrl) {
        URL.revokeObjectURL(prev.previewUrl);
      }

      return null;
    });
  }, []);

  useEffect(() => {
    return () => {
      if (activeSession?.previewUrl) {
        URL.revokeObjectURL(activeSession.previewUrl);
      }
    };
  }, [activeSession?.previewUrl]);

  const performTextSearch = useCallback(
    async (queryToSearch: string) => {
      const trimmedQuery = queryToSearch.trim();
      if (!trimmedQuery) {
        setSearchResults([]);
        setTotalCount(0);
        return;
      }

      const requestId = ++searchRequestIdRef.current;
      setIsSearching(true);

      try {
        const response = await searchApiClient.searchText(trimmedQuery);

        // Ignore stale results
        if (requestId !== searchRequestIdRef.current || !isMountedRef.current) {
          return;
        }

        setSearchResults(response.data);
        setTotalCount(response.totalCount);
        setActiveSession({ mode: "text" });
      } catch (error) {
        if (requestId !== searchRequestIdRef.current || !isMountedRef.current) {
          return;
        }

        logError("Ошибка поиска:", error);
        setSearchResults([]);
        setTotalCount(0);
      } finally {
        if (requestId === searchRequestIdRef.current && isMountedRef.current) {
          setIsSearching(false);
        }
      }
    },
    []
  );

  useEffect(() => {
    if (!searchQuery.trim()) {
      searchRequestIdRef.current++;
      setIsSearching(false);
      clearSearchSession();
      return;
    }

    setActiveSession((prev) => {
      if (prev?.mode === "image") {
        return prev;
      }

      return { mode: "text" };
    });
    setIsSearching(true);

    const timer = setTimeout(() => {
      void performTextSearch(searchQuery);
    }, 300);

    return () => {
      clearTimeout(timer);
    };
  }, [clearSearchSession, performTextSearch, searchQuery]);

  const handlePhotoSearchCapture = useCallback(
    async (blob: Blob) => {
      const file =
        blob instanceof File
          ? blob
          : new File([blob], "search-photo.jpg", {
              type: blob.type || "image/jpeg",
            });

      const previewUrl = URL.createObjectURL(file);
      setSearchQuery("");
      setSearchResults([]);
      setTotalCount(0);
      setIsSearching(true);
      setActiveSession((prev) => {
        if (prev?.previewUrl) {
          URL.revokeObjectURL(prev.previewUrl);
        }

        return {
          mode: "image",
          previewUrl,
          file,
        };
      });

      try {
        const result = await searchApiClient.searchByPhoto(file);
        setSearchResults(result.data);
        setTotalCount(result.totalCount);
      } catch (error) {
        const message =
          error instanceof Error
            ? error.message
            : "Не удалось выполнить поиск по фото";
        toast.error(message);
        clearSearchSession();
      } finally {
        setIsSearching(false);
      }
    },
    [clearSearchSession]
  );

  const isTextQueryActive = searchQuery.trim().length > 0;
  const isSearchActive = activeSession != null || isTextQueryActive;
  const effectiveMode: SearchMode | null = activeSession?.mode ?? (isTextQueryActive ? "text" : null);
  const isPhotoSearchActive = effectiveMode === "image";
  const searchTitle =
    effectiveMode === "image" ? "Результаты поиска по фото" : "Результаты поиска";
  const emptyMessage =
    effectiveMode === "image"
      ? "Похожих вещей не найдено"
      : `Ничего не найдено по запросу "${searchQuery.trim()}"`;
  const bannerStatusText = isSearching
    ? effectiveMode === "image"
      ? "Ищем похожие вещи..."
      : `Ищем по запросу "${searchQuery.trim()}"...`
    : effectiveMode === "image"
      ? totalCount > 0
        ? `Найдено ${totalCount} результатов по фото`
        : "Похожих вещей не найдено"
      : totalCount > 0
        ? `Найдено ${totalCount} результатов`
        : `Ничего не найдено по запросу "${searchQuery.trim()}"`;
  const bannerDescription = "";

  return (
    <div className={cn("flex flex-col w-full mx-auto transition-all duration-500", isSearchActive ? "gap-4" : "gap-8 mt-[10vh] max-w-3xl")}>
      {!isSearchActive && (
         <div className="flex flex-col items-center justify-center text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="relative mb-6">
              <div className="absolute inset-0 -m-4 rounded-full bg-primary/5 blur-2xl" />
              <div className="relative flex h-24 w-24 items-center justify-center rounded-3xl border bg-background/50 shadow-sm backdrop-blur">
                <PackageSearch className="h-10 w-10 text-primary/60" />
              </div>
            </div>
            <h1 className="text-3xl sm:text-4xl font-bold tracking-tight mb-3">Поиск вещей</h1>
            <p className="max-w-md text-balance text-muted-foreground">
              Начните вводить название вещи или контейнера, либо воспользуйтесь поиском по фото для быстрого нахождения.
            </p>
         </div>
      )}

      {isSearchActive && <PageHeader title="Поиск" />}

      <div className={cn("flex items-center relative transition-all duration-300 z-10", isSearchActive ? "" : "shadow-lg hover:shadow-xl rounded-[1.25rem] group")}>
          <InputGroup className={cn("w-full border-border/60 transition-all", isSearchActive ? "h-10 bg-background rounded-lg" : "h-14 sm:h-16 bg-background/80 backdrop-blur rounded-[1.25rem] dark:bg-muted/20")}>
            <InputGroupAddon align="inline-start">
               <Search className={cn("text-muted-foreground", isSearchActive ? "h-4 w-4" : "h-5 w-5 sm:h-6 sm:w-6 ml-1 sm:ml-2")} />
            </InputGroupAddon>
            <InputGroupInput
               autoFocus
               onChange={(event) => {
                 if (isPhotoSearchActive) {
                   clearSearchSession();
                 }
                 setSearchQuery(event.target.value);
               }}
               value={searchQuery}
               placeholder="Введите название вещи или контейнера..."
               className={cn("h-full border-0 focus-visible:ring-0", isSearchActive ? "text-sm" : "text-base sm:text-lg px-2")}
            />

            <div className="pr-1.5 sm:pr-2 flex items-center h-[calc(100%-8px)] my-1">
              <Button
                type="button"
                variant={isPhotoSearchActive ? "default" : "secondary"}
                onClick={() => setIsPhotoSearchOpen(true)}
                disabled={isSearching && isPhotoSearchActive}
                className={cn("h-full transition-all shadow-sm hover:shadow", isSearchActive ? "px-3 rounded-md" : "px-4 sm:px-6 rounded-xl")}
              >
                 {isSearching && isPhotoSearchActive ? (
                   <Loader2 className="animate-spin" data-icon="inline-start" />
                 ) : (
                   <ScanSearch className={cn(isSearchActive ? "mr-2 h-4 w-4" : "mr-2 h-4 w-4 sm:h-5 sm:w-5")} />
                 )}
                 <span className={cn(isSearchActive ? "hidden sm:inline text-sm" : "hidden sm:inline text-sm font-medium")}>
                   Поиск по фото
                 </span>
              </Button>
            </div>
          </InputGroup>
      </div>

      {isSearchActive && effectiveMode ? (
        <SearchSessionBanner
          mode={effectiveMode}
          previewUrl={activeSession?.previewUrl ?? null}
          statusText={bannerStatusText}
          description={bannerDescription}
          onReset={() => {
            clearSearchSession();
            setSearchQuery("");
          }}
        />
      ) : null}

      {isSearchActive && effectiveMode ? (
        <div className="flex flex-col gap-8 animate-in fade-in duration-300">
          <SearchResultsSection
            title={searchTitle}
            hits={searchResults}
            isLoading={isSearching}
            mode={effectiveMode}
            emptyMessage={emptyMessage}
          />
          {effectiveMode === "image" && !isSearching && (
            <div className="flex flex-col items-center justify-center rounded-2xl border border-border/60 bg-gradient-to-br from-muted/40 via-background to-background p-8 text-center shadow-sm">
              <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-primary/10">
                <PlusCircle className="h-6 w-6 text-primary" />
              </div>
              <h3 className="mb-2 text-xl font-semibold tracking-tight text-foreground">
                Не нашли нужную вещь?
              </h3>
              <p className="mb-6 max-w-md text-sm text-muted-foreground/90 leading-relaxed">
                Добавьте новую вещь в каталог. Мы уже проанализировали ваше фото для автоматического заполнения названия и категории.
              </p>
              <Button
                size="lg"
                onClick={() => {
                  if (activeSession?.file) {
                    addItemContext.processPhotoAndOpenForm(activeSession.file).catch((e) => {
                      logError("Error in processPhotoAndOpenForm:", e);
                    });
                  }
                }}
                disabled={addItemContext.isRecognizeLoading}
                className="gap-2 font-medium shadow-sm transition-all hover:shadow-md"
              >
                {addItemContext.isRecognizeLoading ? (
                  <Loader2 className="h-5 w-5 animate-spin" />
                ) : (
                  <PlusCircle className="h-5 w-5" />
                )}
                <span>Добавить вещь</span>
              </Button>
            </div>
          )}
        </div>
      ) : (
        <SearchEmptyState onSuggest={setSearchQuery} />
      )}

      <CameraCaptureDialog
        open={isPhotoSearchOpen}
        onClose={() => setIsPhotoSearchOpen(false)}
        onCapture={handlePhotoSearchCapture}
        title="Поиск по фото"
        hint="Наведите камеру на предмет или загрузите готовую фотографию"
        uploadLabel="Загрузить"
        captureLabel="Найти"
      />
    </div>
  );
}

"use client";

/**
 * useListPage: состояние списка сущностей, URL, загрузка.
 * Поток: ключ запроса (filters + sort + page) → один эффект загрузки → обновление data / totalCount / error.
 * Использует useRequestKey (избежание дублей запросов) и useDebouncedSearch (дебаунс поиска).
 */

import { useState, useCallback, useEffect, useRef, useMemo } from "react";
import { useQueryStates } from "nuqs";
import { useTenant } from "@/contexts/tenant-context";
import { deepEqual } from "@/lib/app/helpers/deep-equal";
import {
  getEntitySortParams,
  sortParamsToOption,
  type EntitySortOption,
} from "@/lib/entities/helpers/sort";
import {
  createListPageParsers,
  urlStateToFilters,
  filtersToUrlState,
} from "@/lib/app/hooks/list-page-url-state";
import { useRequestKey } from "@/lib/app/hooks/use-request-key";
import { useDebouncedSearch } from "@/lib/app/hooks/use-debounced-search";
import { DEFAULT_LIST_PAGE_SIZE } from "@/lib/shared/api/constants";
import type {
  EntityConfig,
  EntityDisplay,
  Filters,
  ListPagePagination,
  Results,
} from "@/types/entity";

export interface EntityListState<T> {
  data: T[];
  isLoading: boolean;
  error: string | null;
  searchQuery: string;
  sort: EntitySortOption;
  filters: Filters;
  isFiltersOpen: boolean;
  results: Results;
}

export function useListPage(config: EntityConfig) {
  const { activeTenantId } = useTenant();
  const {
    filters: filtersConfig,
    columns,
    addForm,
    labels,
    icon,
    getName,
    fetch: fetchData,
    pagination: paginationConfig,
    kind,
    basePath,
    apiTable,
    counts,
  } = config;

  const filterFields = filtersConfig.fields;
  const initialFilters = filtersConfig.initial;
  const results = labels.results;
  const hasPagination = paginationConfig != null;
  const hasAddForm = addForm != null;

  const pageSize = hasPagination ? paginationConfig.pageSize : DEFAULT_LIST_PAGE_SIZE;

  const parsers = useMemo(
    () => createListPageParsers(config.defaultSort),
    [config.defaultSort]
  );
  const [urlState, setUrlState] = useQueryStates(parsers);
  const searchQuery = urlState.search;
  const sort = sortParamsToOption(urlState.sortBy, urlState.sortDirection);
  const filters = urlStateToFilters(urlState, initialFilters);
  const currentPage = urlState.page;

  const [isFiltersOpen, setIsFiltersOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [data, setData] = useState<EntityDisplay[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [addFormOpen, setAddFormOpen] = useState(false);

  const isMountedRef = useRef(true);
  const { shouldStart, isLatest, finish } = useRequestKey();
  const { sortBy, sortDirection } = getEntitySortParams(sort);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const startLoading = useCallback((initial: boolean) => {
    if (initial) setIsLoading(true);
    setError(null);
  }, []);

  const finishLoading = useCallback((initial: boolean) => {
    if (initial) setIsLoading(false);
  }, []);

  const handleError = useCallback((err: unknown, initial: boolean) => {
    setError(err instanceof Error ? err.message : "Произошла ошибка");
    if (initial) setIsLoading(false);
  }, []);

  const loadData = useCallback(
    async (query?: string, isInitialLoad = false, page = 1) => {
      if (!isMountedRef.current) return;

      const requestKey = JSON.stringify({
        query: (query?.trim() ?? ""),
        filters,
        sortBy,
        sortDirection,
        tenantId: activeTenantId,
        ...(hasPagination ? { page } : {}),
      });

      if (!shouldStart(requestKey)) return;

      startLoading(isInitialLoad);

      try {
        const params = {
          query: query?.trim(),
          filterValues: filters,
          sortBy,
          sortDirection,
          tenantId: activeTenantId,
          ...(hasPagination ? { page } : {}),
        };
        const result = await fetchData(params);
        if (!isMountedRef.current || !isLatest(requestKey)) return;
        if (result?.error) {
          setError(result.error);
          setData([]);
          if (hasPagination) setTotalCount(0);
        } else {
          setError(null);
          const list = Array.isArray(result?.data) ? result.data : [];
          setData(list);
          if (hasPagination && result?.totalCount != null) {
            setTotalCount(result.totalCount);
          }
        }
        finishLoading(isInitialLoad);
      } catch (err) {
        if (isMountedRef.current && isLatest(requestKey)) {
          handleError(err, isInitialLoad);
          setData([]);
          if (hasPagination) setTotalCount(0);
        }
      } finally {
        finish(requestKey);
      }
    },
    [
      filters,
      sortBy,
      sortDirection,
      hasPagination,
      activeTenantId,
      fetchData,
      shouldStart,
      isLatest,
      finish,
      startLoading,
      finishLoading,
      handleError,
    ]
  );

  const loadDataRef = useRef(loadData);
  loadDataRef.current = loadData;

  const filtersKey = JSON.stringify(filters);
  useEffect(() => {
    if (activeTenantId == null) {
      setData([]);
      setTotalCount(0);
      setIsLoading(false);
      return;
    }
    const load = loadDataRef.current;
    if (hasPagination) {
      load(searchQuery, true, currentPage);
    } else {
      load(searchQuery, true);
    }
  }, [filtersKey, sortBy, sortDirection, currentPage, activeTenantId, hasPagination, searchQuery]);

  const refreshList = useCallback(() => {
    if (hasPagination) {
      loadData(searchQuery, false, currentPage);
    } else {
      loadData(searchQuery, false);
    }
  }, [loadData, searchQuery, hasPagination, currentPage]);

  const handleSearch = useCallback(
    (query: string) => {
      if (hasPagination) {
        setUrlState({ page: 1 });
        loadData(query || undefined, false, 1);
      } else {
        loadData(query || undefined, false);
      }
    },
    [loadData, hasPagination, setUrlState]
  );

  useDebouncedSearch(searchQuery, handleSearch, { skipInitial: true });

  const handleSearchChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setUrlState({ search: e.target.value });
    },
    [setUrlState]
  );

  const totalPages = hasPagination ? Math.ceil(totalCount / pageSize) : 1;
  const goToPage = useCallback(
    (page: number) => {
      setUrlState({ page });
      loadData(searchQuery, false, page);
    },
    [loadData, searchQuery, setUrlState]
  );

  const pagination: ListPagePagination | undefined = hasPagination
    ? {
        totalCount,
        pageSize,
        totalPages,
        currentPage,
        goToPage,
      }
    : undefined;

  const isAddFormOpen = hasAddForm ? addFormOpen : false;

  const handleAddFormOpenChange = useCallback((open: boolean) => {
    setAddFormOpen(open);
  }, []);

  const handleEntityAdded = useCallback(() => {
    refreshList();
  }, [refreshList]);


  const resultsCount = Array.isArray(data) ? data.length : 0;

  const activeFiltersCount = (() => {
    let count = 0;
    const init = initialFilters as Record<string, unknown>;
    const current = filters as Record<string, unknown>;
    for (const key of Object.keys(current)) {
      if (!deepEqual(current[key], init[key])) count++;
    }
    return count;
  })();

  const setFiltersAndUrl = useCallback(
    (newFilters: Filters) => {
      setUrlState({
        ...filtersToUrlState(newFilters, initialFilters),
        ...(hasPagination ? { page: 1 } : {}),
      });
    },
    [setUrlState, initialFilters, hasPagination]
  );

  const setSortAndUrl = useCallback(
    (newSort: EntitySortOption) => {
      const { sortBy, sortDirection } = getEntitySortParams(newSort);
      setUrlState({ sortBy, sortDirection, ...(hasPagination ? { page: 1 } : {}) });
    },
    [setUrlState, hasPagination]
  );

  const resetFilters = useCallback(() => {
    setFiltersAndUrl(initialFilters);
  }, [setFiltersAndUrl, initialFilters]);

  const baseReturn = {
    data,
    isLoading,
    error,
    searchQuery,
    setSearchQuery: (q: string) => setUrlState({ search: q }),
    handleSearchChange,
    sort,
    setSort: setSortAndUrl,
    filters,
    setFilters: setFiltersAndUrl,
    resetFilters,
    isFiltersOpen,
    setIsFiltersOpen,
    resultsCount,
    results,
    activeFiltersCount,
    filterFields,
    columns,
    addForm,
    icon,
    getName,
    labels,
    kind,
    basePath,
    apiTable,
    counts,
    groupBy: config.groupBy,
    groupByEmptyLabel: config.groupByEmptyLabel,
    refreshList,
  };

  return {
    ...baseReturn,
    pagination,
    ...(hasAddForm && {
      isAddFormOpen,
      handleAddFormOpenChange,
      handleEntityAdded,
    }),
  };
}

/**
 * Загрузка данных страницы детали контейнера: контейнер, transitions, вещи в контейнере.
 * Используется в app/api/containers/[id]/route.ts GET.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { normalizeEntityTypeRelation } from "@/lib/shared/api/normalize-entity-type-relation";
import type {
  Container,
  ContainerDetailData,
  LoadDetailError,
  Transition,
  Location,
  Item,
} from "@/types/entity";

export type { ContainerDetailData, LoadDetailError };

/**
 * Загружает данные контейнера по id. При ошибке БД или отсутствии контейнера возвращает { error, status }.
 */
export async function loadContainerDetail(
  supabase: SupabaseClient,
  containerId: number
): Promise<ContainerDetailData | LoadDetailError> {
  const { data: containerData, error: containerError } = await supabase
    .from("containers")
    .select(
      "id, name, entity_type_id, photo_url, created_at, deleted_at, entity_types(name)"
    )
    .eq("id", containerId)
    .single();

  if (containerError) {
    return { error: containerError.message, status: HTTP_STATUS.INTERNAL_SERVER_ERROR };
  }
  if (!containerData) {
    return { error: "Контейнер не найден", status: HTTP_STATUS.NOT_FOUND };
  }

  const { data: transitionsData, error: transitionsError } = await supabase
    .from("transitions")
    .select("*")
    .eq("container_id", containerId)
    .order("created_at", { ascending: false });

  if (transitionsError) {
    return { error: transitionsError.message, status: HTTP_STATUS.INTERNAL_SERVER_ERROR };
  }

  const placeIds = (transitionsData || [])
    .filter((t) => t.destination_type === "place" && t.destination_id)
    .map((t) => t.destination_id);
  const containerIds = (transitionsData || [])
    .filter((t) => t.destination_type === "container" && t.destination_id)
    .map((t) => t.destination_id);
  const roomIds = (transitionsData || [])
    .filter((t) => t.destination_type === "room" && t.destination_id)
    .map((t) => t.destination_id);
  const furnitureIds = (transitionsData || [])
    .filter((t) => t.destination_type === "furniture" && t.destination_id)
    .map((t) => t.destination_id);

  const [placesData, containersData, roomsData, furnitureData] =
    await Promise.all([
      placeIds.length > 0
        ? supabase
            .from("places")
            .select("id, name")
            .in("id", placeIds)
            .is("deleted_at", null)
        : { data: [] },
      containerIds.length > 0
        ? supabase
            .from("containers")
            .select("id, name")
            .in("id", containerIds)
            .is("deleted_at", null)
        : { data: [] },
      roomIds.length > 0
        ? supabase
            .from("rooms")
            .select("id, name")
            .in("id", roomIds)
            .is("deleted_at", null)
        : { data: [] },
      furnitureIds.length > 0
        ? supabase
            .from("furniture")
            .select("id, name, room_id")
            .in("id", furnitureIds)
            .is("deleted_at", null)
        : { data: [] },
    ]);

  const furnitureRows = (furnitureData?.data || []) as {
    id: number;
    name: string | null;
    room_id: number | null;
  }[];
  const furnitureMap = new Map(
    furnitureRows.map((f) => [f.id, f.name ?? null])
  );
  const furnitureRoomIds = furnitureRows
    .map((f) => f.room_id)
    .filter((id): id is number => id != null);
  const { data: furnitureRoomsData } =
    furnitureRoomIds.length > 0
      ? await supabase
          .from("rooms")
          .select("id, name")
          .in("id", furnitureRoomIds)
          .is("deleted_at", null)
      : { data: [] };
  const furnitureRoomsMap = new Map(
    ((furnitureRoomsData || []) as { id: number; name: string | null }[]).map(
      (r) => [r.id, r.name ?? null]
    )
  );

  const placesMap = new Map(
    (placesData.data || []).map((p: { id: number; name: string | null }) => [
      p.id,
      p.name ?? null,
    ])
  );
  const containersMap = new Map(
    (containersData.data || []).map(
      (c: { id: number; name: string | null }) => [c.id, c.name ?? null]
    )
  );
  const roomsMap = new Map(
    (roomsData.data || []).map((r: { id: number; name: string | null }) => [
      r.id,
      r.name ?? null,
    ])
  );

  const allPlaceIds = Array.from(placesMap.keys());
  const { data: placesTransitionsData } =
    allPlaceIds.length > 0
      ? await supabase
          .from("transitions")
          .select("*")
          .eq("destination_type", "room")
          .in("place_id", allPlaceIds)
          .order("created_at", { ascending: false })
      : { data: [] };

  type PlaceTransitionRow = { place_id: number | null; destination_id: number | null };
  const lastPlaceTransitions = new Map<number, PlaceTransitionRow>();
  (placesTransitionsData || []).forEach((t: PlaceTransitionRow) => {
    if (t.place_id && !lastPlaceTransitions.has(t.place_id)) {
      lastPlaceTransitions.set(t.place_id, t);
    }
  });

  const placeRoomIds = Array.from(lastPlaceTransitions.values())
    .map((t) => t.destination_id)
    .filter((id): id is number => id !== null);

  const { data: placeRoomsData } =
    placeRoomIds.length > 0
      ? await supabase
          .from("rooms")
          .select("id, name")
          .in("id", placeRoomIds)
          .is("deleted_at", null)
      : { data: [] };

  const placeRoomsMap = new Map(
    (placeRoomsData || []).map((r: { id: number; name: string | null }) => [
      r.id,
      r.name ?? null,
    ])
  );

  const transitionsWithNames = (transitionsData || []).map((t): Transition => {
    const transition: Transition = {
      id: t.id,
      created_at: t.created_at,
      destination_type: t.destination_type,
      destination_id: t.destination_id,
    };

    if (t.destination_type === "place" && t.destination_id) {
      transition.destination_name = placesMap.get(t.destination_id) || null;
      const placeTransition = lastPlaceTransitions.get(t.destination_id);
      if (placeTransition?.destination_id) {
        transition.room_name =
          placeRoomsMap.get(placeTransition.destination_id) || null;
      }
    } else if (t.destination_type === "container" && t.destination_id) {
      transition.destination_name =
        containersMap.get(t.destination_id) || null;
    } else if (t.destination_type === "room" && t.destination_id) {
      transition.destination_name = roomsMap.get(t.destination_id) || null;
    } else if (t.destination_type === "furniture" && t.destination_id) {
      transition.destination_name = furnitureMap.get(t.destination_id) || null;
      const furnitureRow = furnitureRows.find((f) => f.id === t.destination_id);
      if (furnitureRow?.room_id) {
        transition.room_name =
          furnitureRoomsMap.get(furnitureRow.room_id) || null;
      }
    }

    return transition;
  });

  const lastTransition = transitionsWithNames[0];
  const lastLocation: Location | null = lastTransition
    ? {
        destination_type: lastTransition.destination_type,
        destination_id: lastTransition.destination_id,
        destination_name: lastTransition.destination_name || null,
        moved_at: lastTransition.created_at,
      }
    : null;

  const entityType = normalizeEntityTypeRelation(containerData.entity_types);

  const container: Container = {
    id: containerData.id,
    name: containerData.name,
    entity_type_id: containerData.entity_type_id || null,
    entity_type: entityType,
    photo_url: containerData.photo_url,
    created_at: containerData.created_at,
    deleted_at: containerData.deleted_at,
    last_location: lastLocation,
  };

  const { data: itemsTransitionsData } = await supabase
    .from("transitions")
    .select("item_id")
    .eq("destination_type", "container")
    .eq("destination_id", containerId);

  let containerItems: Item[] = [];
  if (itemsTransitionsData && itemsTransitionsData.length > 0) {
    const itemIds = Array.from(
      new Set(
        itemsTransitionsData
          .map((t) => t.item_id)
          .filter((id): id is number => id !== null && id !== undefined)
      )
    );

    if (itemIds.length > 0) {
      const { data: allItemTransitionsData } = await supabase
        .from("transitions")
        .select("*")
        .in("item_id", itemIds)
        .order("created_at", { ascending: false });

      const lastItemTransitions = new Map<number, Transition>();
      (allItemTransitionsData || []).forEach((t) => {
        if (t.item_id && !lastItemTransitions.has(t.item_id)) {
          lastItemTransitions.set(t.item_id, t as Transition);
        }
      });

      const itemsInContainer = Array.from(lastItemTransitions.entries())
        .filter(
          ([, transition]) =>
            transition.destination_type === "container" &&
            transition.destination_id === containerId
        )
        .map(([itemId]) => itemId);

      if (itemsInContainer.length > 0) {
        const { data: itemsData } = await supabase
          .from("items")
          .select("id, name, photo_url, created_at, deleted_at")
          .in("id", itemsInContainer)
          .is("deleted_at", null)
          .order("created_at", { ascending: false });

        containerItems = (itemsData || []) as Item[];
      }
    }
  }

  return {
    container,
    transitions: transitionsWithNames,
    items: containerItems,
  };
}

/**
 * Загрузка данных страницы детали места: место, transitions, вещи и контейнеры в месте.
 * Используется в app/api/places/[id]/route.ts GET.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { HTTP_STATUS } from "@/lib/shared/api/http-status";
import { normalizeEntityTypeRelation } from "@/lib/shared/api/normalize-entity-type-relation";
import type {
  LoadDetailError,
  PlaceDetailData,
  Place,
  Transition,
  Location,
  Item,
  Container,
  DestinationType,
} from "@/types/entity";

export type { LoadDetailError, PlaceDetailData };

interface TransitionRow {
  id: number;
  created_at: string;
  item_id?: number | null;
  container_id?: number | null;
  place_id?: number | null;
  destination_type: string;
  destination_id: number | null;
}

/**
 * Загружает данные места по id. При ошибке БД или отсутствии места возвращает { error, status }.
 */
export async function loadPlaceDetail(
  supabase: SupabaseClient,
  placeId: number
): Promise<PlaceDetailData | LoadDetailError> {
  const { data: placeData, error: placeError } = await supabase
    .from("places")
    .select(
      "id, name, entity_type_id, photo_url, created_at, deleted_at, entity_types(name)"
    )
    .eq("id", placeId)
    .single();

  if (placeError) {
    return { error: placeError.message, status: HTTP_STATUS.INTERNAL_SERVER_ERROR };
  }
  if (!placeData) {
    return { error: "Место не найдено", status: HTTP_STATUS.NOT_FOUND };
  }

  const { data: transitionsData, error: transitionsError } = await supabase
    .from("transitions")
    .select("*")
    .eq("place_id", placeId)
    .order("created_at", { ascending: false });

  if (transitionsError) {
    return { error: transitionsError.message, status: HTTP_STATUS.INTERNAL_SERVER_ERROR };
  }

  const furnitureIds = (transitionsData || [])
    .filter((t) => t.destination_type === "furniture" && t.destination_id)
    .map((t) => t.destination_id);

  const furnitureResult =
    furnitureIds.length > 0
      ? await supabase
          .from("furniture")
          .select("id, name, room_id")
          .in("id", furnitureIds)
          .is("deleted_at", null)
      : { data: [] };

  const furnitureMap = new Map(
    (furnitureResult.data || []).map((f: { id: number; name: string | null }) => [
      f.id,
      f.name ?? null,
    ])
  );
  const furnitureRoomIds = (furnitureResult.data || [])
    .map((f: { room_id: number }) => f.room_id)
    .filter(Boolean);
  const furnitureRoomsResult =
    furnitureRoomIds.length > 0
      ? await supabase
          .from("rooms")
          .select("id, name")
          .in("id", furnitureRoomIds)
          .is("deleted_at", null)
      : { data: [] };
  const roomNameByRoomId = new Map(
    (furnitureRoomsResult.data || []).map((r: { id: number; name: string }) => [
      r.id,
      r.name,
    ])
  );

  const transitionsWithNames = (transitionsData || []).map((t): Transition => {
    const transition: Transition = {
      id: t.id,
      created_at: t.created_at,
      destination_type: t.destination_type,
      destination_id: t.destination_id,
    };
    if (t.destination_type === "furniture" && t.destination_id) {
      transition.destination_name = furnitureMap.get(t.destination_id) || null;
    }
    return transition;
  });

  const lastTransition = transitionsWithNames[0];
  const lastLocation: Location | null = lastTransition
    ? {
        destination_type: lastTransition.destination_type,
        destination_id: lastTransition.destination_id,
        destination_name: lastTransition.destination_name || null,
        moved_at: lastTransition.created_at,
      }
    : null;

  const entityType = normalizeEntityTypeRelation(placeData.entity_types);

  let furniture_id: number | null = null;
  let furniture_name: string | null = null;
  let room_id: number | null = null;
  let room_name: string | null = null;

  if (
    lastTransition?.destination_type === "furniture" &&
    lastTransition.destination_id
  ) {
    furniture_id = lastTransition.destination_id;
    furniture_name = furnitureMap.get(furniture_id) || null;
    const furnitureRow = (furnitureResult.data || []).find(
      (f: { id: number; room_id: number }) => f.id === furniture_id
    );
    if (furnitureRow?.room_id != null) {
      room_id = furnitureRow.room_id;
      room_name = roomNameByRoomId.get(furnitureRow.room_id) || null;
    }
  }

  const place: Place = {
    id: placeData.id,
    name: placeData.name,
    entity_type_id: placeData.entity_type_id || null,
    entity_type: entityType,
    photo_url: placeData.photo_url,
    created_at: placeData.created_at,
    deleted_at: placeData.deleted_at,
    last_location: lastLocation,
    furniture_id,
    furniture_name,
    room_id,
    room_name,
    room: room_id ? { id: room_id, name: room_name } : null,
  };

  const { data: allTransitionsData } = await supabase
    .from("transitions")
    .select("item_id, container_id, created_at")
    .eq("destination_type", "place")
    .eq("destination_id", placeId)
    .order("created_at", { ascending: false });

  const itemIdsSet = new Set<number>();
  const containerIdsSet = new Set<number>();
  (allTransitionsData || []).forEach((t) => {
    if (t.item_id) itemIdsSet.add(t.item_id);
    if (t.container_id) containerIdsSet.add(t.container_id);
  });
  const itemIds = Array.from(itemIdsSet);
  const containerIds = Array.from(containerIdsSet);

  let placeItems: Item[] = [];
  let placeContainers: Container[] = [];

  if (itemIds.length > 0 || containerIds.length > 0) {
    let allTransitionsQuery = supabase
      .from("transitions")
      .select("*")
      .order("created_at", { ascending: false });

    if (itemIds.length > 0 && containerIds.length > 0) {
      allTransitionsQuery = allTransitionsQuery.or(
        `item_id.in.(${itemIds.join(",")}),container_id.in.(${containerIds.join(",")})`
      );
    } else if (itemIds.length > 0) {
      allTransitionsQuery = allTransitionsQuery.in("item_id", itemIds);
    } else {
      allTransitionsQuery = allTransitionsQuery.in("container_id", containerIds);
    }

    const { data: allTransitions } = await allTransitionsQuery;
    const lastItemTransitions = new Map<number, Transition>();
    const lastContainerTransitions = new Map<number, Transition>();

    (allTransitions || []).forEach((t: TransitionRow) => {
      const transition: Transition = {
        id: t.id,
        created_at: t.created_at,
        item_id: t.item_id ?? null,
        container_id: t.container_id ?? null,
        place_id: t.place_id ?? null,
        destination_type: (t.destination_type ?? null) as DestinationType | null,
        destination_id: t.destination_id ?? null,
      };
      if (t.item_id && !lastItemTransitions.has(t.item_id)) {
        lastItemTransitions.set(t.item_id, transition);
      }
      if (t.container_id && !lastContainerTransitions.has(t.container_id)) {
        lastContainerTransitions.set(t.container_id, transition);
      }
    });

    const itemsInPlace = Array.from(lastItemTransitions.entries())
      .filter(
        ([, transition]) =>
          transition.destination_type === "place" &&
          transition.destination_id === placeId
      )
      .map(([itemId]) => itemId);

    if (itemsInPlace.length > 0) {
      const { data: itemsData } = await supabase
        .from("items")
        .select("id, name, photo_url, created_at, deleted_at")
        .in("id", itemsInPlace)
        .is("deleted_at", null)
        .order("created_at", { ascending: false });
      placeItems = itemsData || [];
    }

    const containersInPlace = Array.from(lastContainerTransitions.entries())
      .filter(
        ([, transition]) =>
          transition.destination_type === "place" &&
          transition.destination_id === placeId
      )
      .map(([containerId]) => containerId);

    if (containersInPlace.length > 0) {
      const { data: containersData } = await supabase
        .from("containers")
        .select("id, name, photo_url, created_at, deleted_at, entity_type_id")
        .in("id", containersInPlace)
        .is("deleted_at", null)
        .order("created_at", { ascending: false });
      placeContainers = containersData || [];
    }
  }

  return {
    place,
    transitions: transitionsWithNames,
    items: placeItems,
    containers: placeContainers,
  };
}
